-- SVS fresh-project installer. Run once in Supabase SQL Editor.
-- Existing projects: apply only the missing files in migrations/, not this installer.
-- Generated by npm run db:bundle; no demo data, accounts, passwords or keys.
begin;

-- SOURCE: 202610300001_identity.sql
-- Identity foundation. Auth passwords/tokens remain exclusively in Supabase Auth.
create type public.institution_role as enum ('institution_admin','registrar','teacher','student');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '' check(length(full_name)<=200), created_at timestamptz not null default now());
create table public.institutions (
 id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 200), code text not null unique check(code ~ '^[A-Z0-9-]{2,20}$'),
 headquarters text not null default '', contact_email text, logo_url text check(logo_url is null or logo_url ~ '^https://'), active boolean not null default true, created_at timestamptz not null default now()
);
create table public.superadmins (user_id uuid primary key references auth.users(id) on delete cascade);
create table public.memberships (institution_id uuid not null references public.institutions(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.institution_role not null, primary key(institution_id,user_id,role), created_at timestamptz not null default now());
create index memberships_user_idx on public.memberships(user_id,institution_id);
create table public.registration_invites (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id) on delete cascade, email text not null check(email=lower(email) and position('@' in email)>1), role public.institution_role not null, expires_at timestamptz not null default (now()+interval '7 days'), accepted_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create unique index invite_pending_idx on public.registration_invites(institution_id,email,role) where accepted_at is null;
create index invite_email_idx on public.registration_invites(email);
create table public.audit_logs (id bigint generated always as identity primary key, institution_id uuid references public.institutions(id), actor_id uuid, action text not null, record_id text, created_at timestamptz not null default now());
create index audit_institution_idx on public.audit_logs(institution_id,created_at desc);

-- A valid JWT alone is insufficient after a session has been revoked.
create function public.session_is_active() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.sessions s where s.id::text=auth.jwt()->>'session_id' and s.user_id=auth.uid());
$$;
create function public.is_superadmin() returns boolean language sql stable security definer set search_path='' as $$
 select public.session_is_active() and exists(select 1 from public.superadmins where user_id=auth.uid());
$$;
create function public.has_role(inst uuid, roles public.institution_role[] default array['institution_admin','registrar','teacher','student']::public.institution_role[]) returns boolean language sql stable security definer set search_path='' as $$
 select public.is_superadmin() or (public.session_is_active() and exists(select 1 from public.memberships m join public.institutions i on i.id=m.institution_id where m.user_id=auth.uid() and m.institution_id=inst and m.role=any(roles) and i.active));
$$;
create function public.shares_institution(other_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select public.is_superadmin() or (public.session_is_active() and exists(select 1 from public.memberships a join public.memberships b on a.institution_id=b.institution_id join public.institutions i on i.id=a.institution_id where a.user_id=auth.uid() and b.user_id=other_user and a.role='institution_admin' and i.active));
$$;

alter table public.profiles enable row level security;
alter table public.institutions enable row level security;
alter table public.superadmins enable row level security;
alter table public.memberships enable row level security;
alter table public.registration_invites enable row level security;
alter table public.audit_logs enable row level security;
create policy profiles_read on public.profiles for select to authenticated using ((id=auth.uid() and public.session_is_active()) or public.shares_institution(id));
create policy profiles_edit on public.profiles for update to authenticated using (id=auth.uid() and public.session_is_active()) with check(id=auth.uid() and public.session_is_active());
create policy institutions_read on public.institutions for select to authenticated using (public.has_role(id));
create policy institutions_create on public.institutions for insert to authenticated with check(public.is_superadmin());
create policy institutions_edit on public.institutions for update to authenticated using(public.has_role(id,array['institution_admin']::public.institution_role[])) with check(public.has_role(id,array['institution_admin']::public.institution_role[]));
create policy superadmins_read on public.superadmins for select to authenticated using(user_id=auth.uid() and public.session_is_active());
create policy memberships_read on public.memberships for select to authenticated using ((user_id=auth.uid() and public.has_role(institution_id)) or public.has_role(institution_id,array['institution_admin']::public.institution_role[]));
create policy memberships_write on public.memberships for all to authenticated using(public.is_superadmin()) with check(public.is_superadmin());
create policy invitations_read on public.registration_invites for select to authenticated using(public.has_role(institution_id,array['institution_admin']::public.institution_role[]));
create policy invitations_insert on public.registration_invites for insert to authenticated with check(public.is_superadmin() or (role<>'institution_admin' and created_by=auth.uid() and public.has_role(institution_id,array['institution_admin']::public.institution_role[])));
create policy invitations_delete on public.registration_invites for delete to authenticated using(public.has_role(institution_id,array['institution_admin']::public.institution_role[]));
create policy audit_read on public.audit_logs for select to authenticated using(public.is_superadmin() or public.has_role(institution_id,array['institution_admin']::public.institution_role[]));
grant usage on schema public to anon,authenticated;
grant select,update(full_name) on public.profiles to authenticated;
grant select,insert,update on public.institutions to authenticated;
grant select on public.superadmins,public.audit_logs to authenticated;
grant select,insert,delete on public.registration_invites to authenticated;
grant select,insert,update,delete on public.memberships to authenticated;

-- Authoritative signup gate: enable this function as the Before User Created hook.
create function public.before_user_created(event jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=lower(event->'user'->>'email') and v.accepted_at is null and v.expires_at>now() and i.active) then
 return jsonb_build_object('error',jsonb_build_object('http_code',403,'message','Registracija je dostupna samo pozvanim korisnicima.'));
 end if;
 return '{}'::jsonb;
end; $$;
revoke execute on function public.before_user_created(jsonb) from public,anon,authenticated;
grant usage on schema public to supabase_auth_admin;
grant execute on function public.before_user_created(jsonb) to supabase_auth_admin;
create function public.sync_profile_memberships() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),200)) on conflict(id) do nothing;
 if new.email_confirmed_at is not null then
  insert into public.memberships(institution_id,user_id,role) select v.institution_id,new.id,v.role from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=lower(new.email) and v.accepted_at is null and v.expires_at>now() and i.active on conflict do nothing;
  update public.registration_invites set accepted_at=now() where email=lower(new.email) and accepted_at is null and expires_at>now() and institution_id in(select id from public.institutions where active);
 end if;
 return new;
end; $$;
create trigger on_auth_user_sync after insert or update of email_confirmed_at on auth.users for each row execute function public.sync_profile_memberships();
revoke execute on function public.sync_profile_memberships() from public,anon,authenticated;

-- Accept later invitations for an already verified account without a service-role client.
create function public.accept_invitations() returns void language plpgsql security definer set search_path='' as $$
declare verified_email text;
begin
 if not public.session_is_active() then raise exception 'Unauthorized' using errcode='42501'; end if;
 select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
 insert into public.memberships(institution_id,user_id,role) select v.institution_id,auth.uid(),v.role from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=verified_email and v.accepted_at is null and v.expires_at>now() and i.active on conflict do nothing;
 update public.registration_invites set accepted_at=now() where email=verified_email and accepted_at is null and expires_at>now() and institution_id in(select id from public.institutions where active);
end; $$;
create function public.list_my_sessions() returns table(id uuid,created_at timestamptz,updated_at timestamptz,user_agent text,current_session boolean) language sql stable security definer set search_path='' as $$
 select s.id,s.created_at,s.updated_at,s.user_agent,s.id::text=auth.jwt()->>'session_id' from auth.sessions s where s.user_id=auth.uid() and public.session_is_active() order by s.created_at desc;
$$;
create function public.revoke_my_session(target uuid default null, all_sessions boolean default false) returns void language plpgsql security definer set search_path='' as $$
begin
 if not public.session_is_active() then raise exception 'Unauthorized' using errcode='42501'; end if;
 delete from auth.sessions where user_id=auth.uid() and (all_sessions or id=coalesce(target,(auth.jwt()->>'session_id')::uuid));
end; $$;
create function public.audit_identity_change() returns trigger language plpgsql security definer set search_path='' as $$
declare r jsonb;
begin
 r=case when TG_OP='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 insert into public.audit_logs(institution_id,actor_id,action,record_id) values(case when TG_TABLE_NAME='institutions' then (r->>'id')::uuid else (r->>'institution_id')::uuid end,auth.uid(),TG_TABLE_NAME||':'||TG_OP,coalesce(r->>'id',r->>'user_id'));
 return case when TG_OP='DELETE' then old else new end;
end; $$;
create trigger superadmins_audit after insert or delete on public.superadmins for each row execute function public.audit_identity_change();
create trigger institutions_audit after insert or update on public.institutions for each row execute function public.audit_identity_change();
create trigger memberships_audit after insert or update or delete on public.memberships for each row execute function public.audit_identity_change();
create trigger invitations_audit after insert or delete on public.registration_invites for each row execute function public.audit_identity_change();
revoke execute on function public.audit_identity_change() from public,anon,authenticated;
-- Functions default to public execute: remove it explicitly.
revoke execute on function public.session_is_active(),public.is_superadmin(),public.has_role(uuid,public.institution_role[]),public.shares_institution(uuid),public.accept_invitations(),public.list_my_sessions(),public.revoke_my_session(uuid,boolean) from public,anon;
grant execute on function public.session_is_active(),public.is_superadmin(),public.has_role(uuid,public.institution_role[]),public.shares_institution(uuid),public.accept_invitations(),public.list_my_sessions(),public.revoke_my_session(uuid,boolean) to authenticated;

-- SOURCE: 202610300002_academic.sql
-- Academic foundation. All cross-entity references include institution_id.
-- Support verified Auth accounts created before the application migration.
insert into public.profiles(id,full_name) select id,left(coalesce(raw_user_meta_data->>'full_name',''),200) from auth.users on conflict(id) do nothing;
create table public.study_programs (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id), name text not null check(length(name) between 2 and 200), code text not null, degree text not null default 'Prijediplomski', duration_years integer not null check(duration_years between 1 and 8), unique(institution_id,id), unique(institution_id,code));
create table public.academic_years (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id), name text not null check(length(name) between 4 and 30), starts_on date not null, ends_on date not null check(ends_on>starts_on), unique(institution_id,id), unique(institution_id,name));
create table public.semesters (id uuid primary key default gen_random_uuid(), institution_id uuid not null, academic_year_id uuid not null, name text not null check(length(name) between 2 and 80), starts_on date not null, ends_on date not null check(ends_on>starts_on), unique(institution_id,id), foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id), unique(institution_id,academic_year_id,name));
create table public.courses (id uuid primary key default gen_random_uuid(), institution_id uuid not null, program_id uuid not null, semester_id uuid not null, name text not null check(length(name) between 2 and 200), code text not null check(length(code) between 2 and 30), ects numeric(4,1) not null check(ects>0 and ects<=30), unique(institution_id,id), unique(institution_id,semester_id,code), foreign key(institution_id,program_id) references public.study_programs(institution_id,id), foreign key(institution_id,semester_id) references public.semesters(institution_id,id));
create table public.student_studies (id uuid primary key default gen_random_uuid(), institution_id uuid not null, student_id uuid not null references public.profiles(id), program_id uuid not null, academic_year_id uuid not null, study_year integer not null check(study_year between 1 and 8), student_number text not null check(length(student_number) between 2 and 40), status text not null default 'active' check(status in ('active','completed','paused')), unique(institution_id,id), unique(institution_id,id,student_id), unique(institution_id,student_id,program_id,academic_year_id), foreign key(institution_id,program_id) references public.study_programs(institution_id,id), foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id));
create table public.course_enrollments (id uuid primary key default gen_random_uuid(), institution_id uuid not null, study_id uuid not null, course_id uuid not null, student_id uuid not null, enrolled_at timestamptz not null default now(), unique(institution_id,course_id,student_id), foreign key(institution_id,study_id,student_id) references public.student_studies(institution_id,id,student_id), foreign key(institution_id,course_id) references public.courses(institution_id,id));
create table public.course_teachers (id uuid primary key default gen_random_uuid(), institution_id uuid not null, course_id uuid not null, teacher_id uuid not null references public.profiles(id), unique(institution_id,course_id,teacher_id), foreign key(institution_id,course_id) references public.courses(institution_id,id));
create table public.teaching_groups (id uuid primary key default gen_random_uuid(), institution_id uuid not null, course_id uuid not null, name text not null check(length(name) between 1 and 80), unique(institution_id,id), unique(institution_id,course_id,id), unique(institution_id,course_id,name), foreign key(institution_id,course_id) references public.courses(institution_id,id));
create table public.group_members (id uuid primary key default gen_random_uuid(), institution_id uuid not null, course_id uuid not null, group_id uuid not null, student_id uuid not null, unique(group_id,student_id), foreign key(institution_id,course_id,group_id) references public.teaching_groups(institution_id,course_id,id), foreign key(institution_id,course_id,student_id) references public.course_enrollments(institution_id,course_id,student_id));
create table public.rooms (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id), name text not null check(length(name) between 1 and 100), capacity integer not null check(capacity>0), unique(institution_id,id), unique(institution_id,name));
create table public.schedule_entries (id uuid primary key default gen_random_uuid(), institution_id uuid not null, course_id uuid not null, teacher_id uuid not null, room_id uuid not null, group_id uuid, title text not null check(length(title) between 2 and 200), starts_at timestamptz not null, ends_at timestamptz not null check(ends_at>starts_at), unique(institution_id,id), foreign key(institution_id,course_id,teacher_id) references public.course_teachers(institution_id,course_id,teacher_id), foreign key(institution_id,room_id) references public.rooms(institution_id,id), foreign key(institution_id,course_id,group_id) references public.teaching_groups(institution_id,course_id,id));
create table public.exams (id uuid primary key default gen_random_uuid(), institution_id uuid not null, course_id uuid not null, room_id uuid not null, starts_at timestamptz not null, registration_deadline timestamptz not null, withdrawal_deadline timestamptz not null, capacity integer not null check(capacity>0), unique(institution_id,id), check(registration_deadline<=starts_at and withdrawal_deadline<=starts_at), foreign key(institution_id,course_id) references public.courses(institution_id,id), foreign key(institution_id,room_id) references public.rooms(institution_id,id));
create table public.exam_registrations (id uuid primary key default gen_random_uuid(), institution_id uuid not null, exam_id uuid not null, student_id uuid not null references public.profiles(id), status text not null default 'registered' check(status in ('registered','cancelled')), registered_at timestamptz not null default now(), unique(institution_id,exam_id,student_id), foreign key(institution_id,exam_id) references public.exams(institution_id,id));
create table public.grades (id uuid primary key default gen_random_uuid(), institution_id uuid not null, exam_id uuid not null, student_id uuid not null, grade integer not null check(grade between 1 and 5), feedback text not null default '' check(length(feedback)<=2000), graded_by uuid not null references public.profiles(id), graded_at timestamptz not null default now(), unique(institution_id,exam_id,student_id), foreign key(institution_id,exam_id,student_id) references public.exam_registrations(institution_id,exam_id,student_id));
create table public.announcements (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id), course_id uuid, title text not null check(length(title) between 2 and 200), body text not null check(length(body) between 2 and 5000), author_id uuid not null default auth.uid() references public.profiles(id), published_at timestamptz not null default now(), foreign key(institution_id,course_id) references public.courses(institution_id,id));
create index enrollment_student_idx on public.course_enrollments(student_id,institution_id);
create index study_student_idx on public.student_studies(student_id,institution_id);
create index teacher_user_idx on public.course_teachers(teacher_id,institution_id);
create index schedule_time_idx on public.schedule_entries(institution_id,starts_at);
create index exam_time_idx on public.exams(institution_id,starts_at);
create index registration_student_idx on public.exam_registrations(student_id,exam_id);
create index grades_student_idx on public.grades(student_id,institution_id);
create index group_student_idx on public.group_members(student_id,course_id);
create index announcement_time_idx on public.announcements(institution_id,published_at desc);

create function public.academic_manager(inst uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role(inst,array['institution_admin','registrar']::public.institution_role[]); $$;
create function public.teaches(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.course_teachers t where t.course_id=target and t.teacher_id=auth.uid() and public.has_role(t.institution_id,array['teacher']::public.institution_role[])); $$;
create function public.enrolled(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.course_enrollments e join public.student_studies s on s.id=e.study_id where e.course_id=target and e.student_id=auth.uid() and s.status='active' and public.has_role(e.institution_id,array['student']::public.institution_role[])); $$;
create function public.course_staff(inst uuid,target uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.academic_manager(inst) or public.teaches(target); $$;
create function public.exam_staff(inst uuid,target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.exams e where e.id=target and e.institution_id=inst and public.course_staff(inst,e.course_id)); $$;
create function public.sees_student(inst uuid,target uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.academic_manager(inst) or (auth.uid()=target and public.has_role(inst)) or exists(select 1 from public.course_enrollments e where e.institution_id=inst and e.student_id=target and public.teaches(e.course_id)); $$;
create or replace function public.shares_institution(other_user uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_superadmin() or exists(select 1 from public.memberships b where b.user_id=other_user and public.sees_student(b.institution_id,other_user)); $$;
create policy enrolled_teacher_profiles on public.profiles for select to authenticated using(exists(select 1 from public.course_teachers t where t.teacher_id=profiles.id and public.enrolled(t.course_id)));
create policy memberships_registrar_read on public.memberships for select to authenticated using(public.academic_manager(institution_id));

-- Catalogue tables are visible to members; modification belongs to institution staff.
do $$ declare t text; begin
 foreach t in array array['study_programs','academic_years','semesters','courses','rooms','teaching_groups','course_teachers'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 execute format('create policy catalog_read on public.%I for select to authenticated using(public.has_role(institution_id))',t);
 execute format('create policy catalog_manage on public.%I for all to authenticated using(public.academic_manager(institution_id)) with check(public.academic_manager(institution_id))',t);
 end loop;
 foreach t in array array['student_studies','course_enrollments','group_members','schedule_entries','exams','exam_registrations','grades','announcements'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 end loop;
 foreach t in array array['student_studies','course_enrollments','group_members'] loop
 execute format('grant insert,update,delete on public.%I to authenticated',t);
 execute format('create policy students_read on public.%I for select to authenticated using(public.sees_student(institution_id,student_id))',t);
 execute format('create policy students_manage on public.%I for all to authenticated using(public.academic_manager(institution_id)) with check(public.academic_manager(institution_id))',t);
 end loop;
end $$;
-- Enrolment rosters are course-scoped: a teacher cannot read unrelated courses of a student.
drop policy students_read on public.course_enrollments;
create policy enrollment_read on public.course_enrollments for select to authenticated using((student_id=auth.uid() and public.has_role(institution_id)) or public.course_staff(institution_id,course_id));
drop policy students_read on public.group_members;
create policy group_read on public.group_members for select to authenticated using((student_id=auth.uid() and public.has_role(institution_id)) or public.course_staff(institution_id,course_id));
grant insert,update,delete on public.exams,public.schedule_entries,public.announcements to authenticated;
create policy exams_read on public.exams for select to authenticated using(public.enrolled(course_id) or public.course_staff(institution_id,course_id) or (public.has_role(institution_id) and exists(select 1 from public.exam_registrations r where r.exam_id=exams.id and r.student_id=auth.uid())));
create policy exams_manage on public.exams for all to authenticated using(public.course_staff(institution_id,course_id)) with check(public.course_staff(institution_id,course_id));
create policy schedule_read on public.schedule_entries for select to authenticated using(public.course_staff(institution_id,course_id) or (public.enrolled(course_id) and (group_id is null or exists(select 1 from public.group_members g where g.group_id=schedule_entries.group_id and g.student_id=auth.uid()))));
create policy schedule_manage on public.schedule_entries for all to authenticated using(public.course_staff(institution_id,course_id)) with check(public.course_staff(institution_id,course_id) and (public.academic_manager(institution_id) or teacher_id=auth.uid()));
create policy registrations_read on public.exam_registrations for select to authenticated using((student_id=auth.uid() and public.has_role(institution_id)) or public.exam_staff(institution_id,exam_id));
create policy grades_read on public.grades for select to authenticated using((student_id=auth.uid() and public.has_role(institution_id)) or public.exam_staff(institution_id,exam_id));
create policy announcement_read on public.announcements for select to authenticated using(public.has_role(institution_id) and (course_id is null or public.enrolled(course_id) or public.course_staff(institution_id,course_id)));
create policy announcement_manage on public.announcements for all to authenticated using(public.academic_manager(institution_id) or (author_id=auth.uid() and public.teaches(course_id))) with check(author_id=auth.uid() and (public.academic_manager(institution_id) or public.teaches(course_id)));

-- Integrity guards also apply to direct PostgREST calls, not just web forms.
create function public.academic_integrity() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_TABLE_NAME='semesters' then
  if not exists(select 1 from public.academic_years y where y.id=new.academic_year_id and new.starts_on>=y.starts_on and new.ends_on<=y.ends_on) then raise exception 'Semestar mora biti unutar akademske godine.'; end if;
 elsif TG_TABLE_NAME='student_studies' then
  if not exists(select 1 from public.memberships m where m.institution_id=new.institution_id and m.user_id=new.student_id and m.role='student') then raise exception 'Korisnik nije student ustanove.'; end if;
 elsif TG_TABLE_NAME='course_teachers' then
  if not exists(select 1 from public.memberships m where m.institution_id=new.institution_id and m.user_id=new.teacher_id and m.role='teacher') then raise exception 'Korisnik nije nastavnik ustanove.'; end if;
 elsif TG_TABLE_NAME='course_enrollments' then
  if not exists(select 1 from public.student_studies s join public.courses c on c.id=new.course_id join public.semesters sem on sem.id=c.semester_id where s.id=new.study_id and s.program_id=c.program_id and s.academic_year_id=sem.academic_year_id and s.status='active') then raise exception 'Kolegij ne pripada aktivnom studiju i akademskoj godini.'; end if;
 end if;
 return new;
end; $$;
create trigger semester_integrity before insert or update on public.semesters for each row execute function public.academic_integrity();
create trigger study_integrity before insert or update on public.student_studies for each row execute function public.academic_integrity();
create trigger teacher_integrity before insert or update on public.course_teachers for each row execute function public.academic_integrity();
create trigger enrollment_integrity before insert or update on public.course_enrollments for each row execute function public.academic_integrity();
create function public.schedule_integrity() returns trigger language plpgsql security definer set search_path='' as $$
begin
 -- Serialize overlapping writes by teacher and room, including concurrent requests.
 perform 1 from public.profiles where id=new.teacher_id for update;
 perform 1 from public.rooms where id=new.room_id for update;
 if new.group_id is not null then perform 1 from public.teaching_groups where id=new.group_id for update; end if;
 if exists(select 1 from public.schedule_entries s where s.id<>new.id and (s.room_id=new.room_id or s.teacher_id=new.teacher_id or (new.group_id is not null and s.group_id=new.group_id)) and s.starts_at<new.ends_at and s.ends_at>new.starts_at) then raise exception 'Termin se preklapa s dvoranom, nastavnikom ili grupom.'; end if;
 return new;
end; $$;
create trigger schedule_integrity before insert or update on public.schedule_entries for each row execute function public.schedule_integrity();

create function public.register_exam(target uuid,cancel boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare e public.exams; existing_status text;
begin
 perform 1 from public.profiles where id=auth.uid() for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.enrolled(e.course_id) then raise exception 'Nemate pravo pristupa ispitu.' using errcode='42501'; end if;
 if exists(select 1 from public.grades where exam_id=e.id and student_id=auth.uid()) then raise exception 'Ispit je već ocijenjen.'; end if;
 if cancel then
  if now()>e.withdrawal_deadline then raise exception 'Rok za odjavu je istekao.'; end if;
  update public.exam_registrations set status='cancelled' where exam_id=e.id and student_id=auth.uid() and status='registered';
 else
  if now()>e.registration_deadline then raise exception 'Rok za prijavu je istekao.'; end if;
  if exists(select 1 from public.grades g join public.exams x on x.id=g.exam_id join public.courses c on c.id=x.course_id join public.courses own on own.id=e.course_id where g.student_id=auth.uid() and g.grade>1 and c.institution_id=e.institution_id and c.code=own.code) then raise exception 'Kolegij je već položen.'; end if;
  select status into existing_status from public.exam_registrations where exam_id=e.id and student_id=auth.uid();
  if existing_status='registered' then return; end if;
  if (select count(*) from public.exam_registrations where exam_id=e.id and status='registered')>=e.capacity then raise exception 'Ispitni rok je popunjen.'; end if;
  insert into public.exam_registrations(institution_id,exam_id,student_id) values(e.institution_id,e.id,auth.uid()) on conflict(institution_id,exam_id,student_id) do update set status='registered',registered_at=now();
 end if;
end; $$;
create function public.record_grade(target uuid,student uuid,result integer,note text default '') returns void language plpgsql security definer set search_path='' as $$
declare e public.exams;
begin
 perform 1 from public.profiles where id=student for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.course_staff(e.institution_id,e.course_id) then raise exception 'Nemate pravo ocjenjivanja.' using errcode='42501'; end if;
 if e.starts_at>now() then raise exception 'Ispit još nije održan.'; end if;
 if not exists(select 1 from public.exam_registrations r where r.exam_id=e.id and r.student_id=student and r.status='registered') then raise exception 'Student nije prijavljen na ispit.'; end if;
 insert into public.grades(institution_id,exam_id,student_id,grade,feedback,graded_by) values(e.institution_id,e.id,student,result,note,auth.uid()) on conflict(institution_id,exam_id,student_id) do update set grade=result,feedback=note,graded_by=auth.uid(),graded_at=now();
 if result>1 then
  update public.exam_registrations r set status='cancelled' from public.exams other_exam,public.courses other_course,public.courses own_course where r.exam_id=other_exam.id and other_exam.course_id=other_course.id and own_course.id=e.course_id and other_course.institution_id=e.institution_id and other_course.code=own_course.code and r.student_id=student and r.status='registered' and other_exam.starts_at>now() and other_exam.id<>e.id;
 end if;
end; $$;
-- Audit records never contain grades, feedback, tokens or passwords.
do $$ declare t text; begin
 foreach t in array array['study_programs','academic_years','semesters','courses','student_studies','course_enrollments','course_teachers','teaching_groups','group_members','rooms','schedule_entries','exams','exam_registrations','grades','announcements'] loop
 execute format('create trigger academic_audit after insert or update or delete on public.%I for each row execute function public.audit_identity_change()',t);
 end loop;
end $$;
revoke execute on function public.academic_integrity(),public.schedule_integrity() from public,anon,authenticated;
revoke execute on function public.academic_manager(uuid),public.teaches(uuid),public.enrolled(uuid),public.course_staff(uuid,uuid),public.exam_staff(uuid,uuid),public.sees_student(uuid,uuid),public.register_exam(uuid,boolean),public.record_grade(uuid,uuid,integer,text) from public,anon;
grant execute on function public.academic_manager(uuid),public.teaches(uuid),public.enrolled(uuid),public.course_staff(uuid,uuid),public.exam_staff(uuid,uuid),public.sees_student(uuid,uuid),public.register_exam(uuid,boolean),public.record_grade(uuid,uuid,integer,text) to authenticated;

-- Preserve referential and ECTS history under updates as well as inserts.
create function public.academic_update_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare keys text[]; k text;
begin
 if new.institution_id<>old.institution_id then raise exception 'Ustanova zapisa ne može se mijenjati.'; end if;
 if TG_TABLE_NAME='courses' then
  if exists(select 1 from public.course_enrollments where course_id=old.id) and (new.program_id<>old.program_id or new.semester_id<>old.semester_id or new.code<>old.code or new.ects<>old.ects) then raise exception 'Upisani kolegij zadržava program, semestar, šifru i ECTS.'; end if;
 elsif TG_TABLE_NAME='student_studies' then
  if exists(select 1 from public.course_enrollments where study_id=old.id) and (new.student_id<>old.student_id or new.program_id<>old.program_id or new.academic_year_id<>old.academic_year_id) then raise exception 'Studij s upisanim kolegijima zadržava studenta, program i godinu.'; end if;
 elsif TG_TABLE_NAME='semesters' then
  if new.academic_year_id<>old.academic_year_id and exists(select 1 from public.courses where semester_id=old.id) then raise exception 'Semestar s kolegijima zadržava akademsku godinu.'; end if;
 elsif TG_TABLE_NAME='academic_years' then
  if exists(select 1 from public.semesters where academic_year_id=old.id and (starts_on<new.starts_on or ends_on>new.ends_on)) then raise exception 'Akademska godina mora obuhvaćati semestre.'; end if;
 elsif TG_TABLE_NAME='exams' then
  if new.course_id<>old.course_id and exists(select 1 from public.exam_registrations where exam_id=old.id) then raise exception 'Ispit s prijavama zadržava kolegij.'; end if;
 end if;
 return new;
end; $$;
do $$ declare t text; begin foreach t in array array['study_programs','academic_years','semesters','courses','student_studies','course_enrollments','course_teachers','teaching_groups','group_members','rooms','schedule_entries','exams','announcements'] loop execute format('create trigger academic_update_guard before update on public.%I for each row execute function public.academic_update_guard()',t); end loop; end $$;
create function public.exam_integrity() returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform 1 from public.rooms where id=new.room_id for update;
 if new.capacity>(select capacity from public.rooms where id=new.room_id) then raise exception 'Kapacitet ispita prelazi kapacitet dvorane.'; end if;
 if TG_OP='UPDATE' then
  if new.capacity<(select count(*) from public.exam_registrations where exam_id=new.id and status='registered') then raise exception 'Kapacitet je manji od broja prijavljenih.'; end if;
 end if;
 return new;
end; $$;
create trigger exam_integrity before insert or update on public.exams for each row execute function public.exam_integrity();
revoke execute on function public.academic_update_guard(),public.exam_integrity() from public,anon,authenticated;

-- SOURCE: 202611020001_email_domains.sql
-- Empty domain lists deny new invitations and membership activation.
-- Existing memberships are deliberately preserved; configure each institution after upgrade.
create function public.valid_email_domains(domains text[]) returns boolean
language sql immutable set search_path='' as $$
 select cardinality(domains) <= 20 and array_position(domains, null) is null
 and not exists(select 1 from unnest(domains) d where length(d)>253 or
 d !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$');
$$;
alter table public.institutions add column email_domains text[] not null default '{}'
 check(public.valid_email_domains(email_domains));

create function public.institution_email_allowed(inst uuid, address text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.institutions i where i.id=inst and i.active
 and address ~ '^[^@]+@[^@]+$' and lower(split_part(address,'@',2))=any(i.email_domains));
$$;
revoke execute on function public.institution_email_allowed(uuid,text) from public,anon,authenticated;

-- Enforce invitations even through direct PostgREST/SQL writes.
create function public.check_invitation_domain() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if not public.institution_email_allowed(new.institution_id,new.email) then
  raise exception 'E-adresa nije na dopuštenoj domeni aktivne ustanove.' using errcode='23514';
 end if;
 return new;
end; $$;
revoke execute on function public.check_invitation_domain() from public,anon,authenticated;
create trigger invitation_domain_check before insert or update of email,institution_id
 on public.registration_invites for each row execute function public.check_invitation_domain();

create or replace function public.before_user_created(event jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=lower(event->'user'->>'email') and v.accepted_at is null and v.expires_at>now() and i.active and public.institution_email_allowed(i.id, event->'user'->>'email')) then
 return jsonb_build_object('error',jsonb_build_object('http_code',403,'message','Registracija zahtijeva poziv i dopuštenu domenu e-pošte ustanove.'));
 end if;
 return '{}'::jsonb;
end; $$;

create or replace function public.sync_profile_memberships() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),200)) on conflict(id) do nothing;
 if new.email_confirmed_at is not null then
  insert into public.memberships(institution_id,user_id,role) select v.institution_id,new.id,v.role from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=lower(new.email) and v.accepted_at is null and v.expires_at>now() and i.active and public.institution_email_allowed(i.id, new.email) on conflict do nothing;
  update public.registration_invites set accepted_at=now() where email=lower(new.email) and accepted_at is null and expires_at>now() and institution_id in(select id from public.institutions where active and public.institution_email_allowed(id, new.email));
 end if;
 return new;
end; $$;

create or replace function public.accept_invitations() returns void language plpgsql security definer set search_path='' as $$
declare verified_email text;
begin
 if not public.session_is_active() then raise exception 'Unauthorized' using errcode='42501'; end if;
 select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
 insert into public.memberships(institution_id,user_id,role) select v.institution_id,auth.uid(),v.role from public.registration_invites v join public.institutions i on i.id=v.institution_id where v.email=verified_email and v.accepted_at is null and v.expires_at>now() and i.active and public.institution_email_allowed(i.id, verified_email) on conflict do nothing;
 update public.registration_invites set accepted_at=now() where email=verified_email and accepted_at is null and expires_at>now() and institution_id in(select id from public.institutions where active and public.institution_email_allowed(id, verified_email));
end; $$;

-- SOURCE: 202611020002_import_passwords.sql
-- Imported accounts can authenticate only to replace their temporary password.
-- Check authoritative Auth metadata rather than stale JWT claims.
create function public.password_change_session_is_active() returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.sessions s where s.id::text=auth.jwt()->>'session_id' and s.user_id=auth.uid());
$$;
revoke execute on function public.password_change_session_is_active() from public,anon;
grant execute on function public.password_change_session_is_active() to authenticated,service_role;

create or replace function public.session_is_active() returns boolean
language sql stable security definer set search_path='' as $$
 select public.password_change_session_is_active() and exists(select 1 from auth.users u
 where u.id=auth.uid() and coalesce(u.raw_app_meta_data->>'svs_password_change_required','false') <> 'true');
$$;

create function public.clear_import_password_requirement() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.encrypted_password is distinct from old.encrypted_password then
  new.raw_app_meta_data = coalesce(new.raw_app_meta_data,'{}'::jsonb) - 'svs_password_change_required';
 end if;
 return new;
end; $$;
revoke execute on function public.clear_import_password_requirement() from public,anon,authenticated;
create trigger import_password_changed before update of encrypted_password on auth.users
 for each row execute function public.clear_import_password_requirement();

-- SOURCE: 202611020003_pending_credentials.sql
-- Reserve one issuance per pending invitation before calling the Auth Admin API.
alter table public.registration_invites add column credentials_issued_at timestamptz;
create function public.claim_pending_credentials(invite_id uuid)
returns table(email text, institution_id uuid, existing_user_id uuid)
language plpgsql security definer set search_path='' as $$
declare invitation public.registration_invites; auth_user auth.users;
begin
 if not public.is_superadmin() then raise exception 'Forbidden' using errcode='42501'; end if;
 select * into invitation from public.registration_invites v where v.id=invite_id for update;
 if invitation.id is null or invitation.accepted_at is not null or invitation.expires_at<=now()
 or invitation.credentials_issued_at is not null
 or not public.institution_email_allowed(invitation.institution_id,invitation.email) then
  raise exception 'Invitation unavailable' using errcode='23514';
 end if;
 select * into auth_user from auth.users u where lower(u.email)=invitation.email;
 if auth_user.email_confirmed_at is not null then raise exception 'Account already confirmed' using errcode='23514'; end if;
 update public.registration_invites v set credentials_issued_at=now() where v.id=invite_id;
 return query select invitation.email,invitation.institution_id,auth_user.id;
end; $$;
revoke execute on function public.claim_pending_credentials(uuid) from public,anon;
grant execute on function public.claim_pending_credentials(uuid) to authenticated;

-- SOURCE: 202611020004_student_services.sql
-- Student self-reported annual data is separate from registrar-controlled entitlements.
create table public.student_reports (
 id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id),
 student_id uuid not null references public.profiles(id) on delete cascade, academic_year_id uuid not null,
 personal jsonb not null default '{}' check(jsonb_typeof(personal)='object' and octet_length(personal::text)<=16000),
 preferences jsonb not null default '{}' check(jsonb_typeof(preferences)='object' and octet_length(preferences::text)<=2000),
 unique(institution_id,student_id,academic_year_id),
 foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id)
);
create table public.student_services (
 id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id),
 student_id uuid not null references public.profiles(id) on delete cascade, academic_year_id uuid not null,
 kind text not null check(kind in ('dining','extra_ects','tuition','participation','mobility','category','attendance','certificate')),
 payload jsonb not null check(jsonb_typeof(payload)='object' and octet_length(payload::text)<=16000),
 foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id)
);
create function public.is_institution_student(inst uuid,student uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select (public.academic_manager(inst) or (auth.uid()=student and public.has_role(inst))) and exists(select 1 from public.memberships m where m.institution_id=inst and m.user_id=student and m.role='student');
$$;
revoke execute on function public.is_institution_student(uuid,uuid) from public,anon;
grant execute on function public.is_institution_student(uuid,uuid) to authenticated;
alter table public.student_reports enable row level security;
alter table public.student_services enable row level security;
create policy reports_read on public.student_reports for select to authenticated using(public.academic_manager(institution_id) or (student_id=auth.uid() and public.has_role(institution_id)));
create policy reports_write on public.student_reports for insert to authenticated with check(student_id=auth.uid() and public.has_role(institution_id,array['student']::public.institution_role[]));
create policy reports_edit on public.student_reports for update to authenticated using(student_id=auth.uid() and public.has_role(institution_id,array['student']::public.institution_role[])) with check(student_id=auth.uid() and public.has_role(institution_id,array['student']::public.institution_role[]));
create policy services_read on public.student_services for select to authenticated using(public.academic_manager(institution_id) or (student_id=auth.uid() and public.has_role(institution_id)));
create policy services_manage on public.student_services for all to authenticated using(public.academic_manager(institution_id)) with check(public.academic_manager(institution_id) and public.is_institution_student(institution_id,student_id));
grant select,insert,update on public.student_reports to authenticated;
grant select,insert,update,delete on public.student_services to authenticated;
create trigger student_services_audit after insert or update or delete on public.student_services for each row execute function public.audit_identity_change();
create index student_services_lookup on public.student_services(institution_id,student_id,academic_year_id,kind);
create index student_reports_lookup on public.student_reports(institution_id,student_id);
alter table public.courses add column lecture_hours integer not null default 0 check(lecture_hours between 0 and 1000),
 add column exercise_hours integer not null default 0 check(exercise_hours between 0 and 1000),
 add column elective_group text not null default '' check(length(elective_group)<=200),
 add column teaching_plan text not null default '' check(length(teaching_plan)<=5000);
alter table public.institutions add column registrar_contact text not null default '' check(length(registrar_contact)<=2000),
 add column student_instructions text not null default '' check(length(student_instructions)<=5000),
 add column identity_portal_url text not null default '' check(identity_portal_url='' or identity_portal_url ~ '^https://');
create unique index extra_ects_reference on public.student_services(institution_id,student_id,(payload->>'reference')) where kind='extra_ects';
-- Aggregates are available to enrolled students and managers, never peer-level rows.
create function public.student_cohort_summary(inst uuid,program uuid,year_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if not public.academic_manager(inst) and not (public.has_role(inst,array['student']::public.institution_role[]) and exists(select 1 from public.student_studies s where s.institution_id=inst and s.student_id=auth.uid() and s.program_id=program and s.academic_year_id=year_id)) then
  raise exception 'Forbidden' using errcode='42501';
 end if;
 with cohort as (select distinct s.student_id,s.id from public.student_studies s where s.institution_id=inst and s.program_id=program and s.academic_year_id=year_id),
 enrolled as (select distinct co.student_id,c.code,c.id,c.ects from cohort co join public.course_enrollments e on e.study_id=co.id join public.courses c on c.id=e.course_id),
 passed as (select distinct on (e.student_id,e.code) e.student_id,e.code,e.ects,g.grade from enrolled e join public.exams x on x.course_id=e.id join public.grades g on g.exam_id=x.id and g.student_id=e.student_id where g.grade>1 order by e.student_id,e.code,g.graded_at desc),
 totals as (select co.student_id,
 (select coalesce(sum(e.ects),0) from enrolled e where e.student_id=co.student_id) enrolled_ects,
 (select coalesce(sum(p.ects),0) from passed p where p.student_id=co.student_id) earned_ects,
 (select avg(p.grade) from passed p where p.student_id=co.student_id) grade,
 (select count(*) from enrolled e where e.student_id=co.student_id) enrolled_courses,
 (select count(*) from passed p where p.student_id=co.student_id) passed_courses
 from (select distinct student_id from cohort) co)
 select case when count(*)<5 then jsonb_build_object('available',false) else jsonb_build_object('available',true,'average_enrolled_ects',avg(enrolled_ects),'average_earned_ects',avg(earned_ects),'average_grade',avg(grade),'average_enrolled_courses',avg(enrolled_courses),'average_passed_courses',avg(passed_courses)) end into result from totals;
 return result;
end; $$;
revoke execute on function public.student_cohort_summary(uuid,uuid,uuid) from public,anon;
grant execute on function public.student_cohort_summary(uuid,uuid,uuid) to authenticated;

-- Non-credit courses (e.g. physical education) are valid catalogue entries.
alter table public.courses drop constraint courses_ects_check;
alter table public.courses add constraint courses_ects_check check(ects between 0 and 30 and mod(ects,0.5)=0);

-- SOURCE: 202611030001_verified_admissions.sql
-- Only the system administrator configures and reviews cross-project admissions.
create table public.admission_import_mappings (
 id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id),
 program_id uuid not null, academic_year_id uuid not null,
 source_school_id text not null check(length(source_school_id) between 1 and 200),
 source_program_id uuid not null, source_year_id uuid not null, candidate_year_id uuid not null,
 domain text not null check(domain=lower(domain)), matura_required boolean not null default true,
 requirements_reference text not null check(length(requirements_reference) between 3 and 500),
 enabled boolean not null default true, revision integer not null default 1, unique(source_school_id,source_program_id,source_year_id,candidate_year_id),
 unique(id,institution_id),
 foreign key(institution_id,program_id) references public.study_programs(institution_id,id),
 foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id)
);
create table public.admission_import_reviews (
 id uuid primary key default gen_random_uuid(), mapping_id uuid not null, institution_id uuid not null,
 candidate_id uuid not null, source_student_id uuid not null, source_choice_id uuid not null, mapping_revision integer not null, graduation_verified boolean not null default false,
 matura_verified boolean not null default false, conditions_verified boolean not null default false,
 evidence_reference text not null check(length(evidence_reference) between 3 and 1000),
 reviewed_by uuid not null default auth.uid() references auth.users(id), reviewed_at timestamptz not null default now(),
 unique(mapping_id,candidate_id), foreign key(mapping_id,institution_id) references public.admission_import_mappings(id,institution_id)
);
create table public.admission_import_jobs (
 id uuid primary key default gen_random_uuid(), mapping_id uuid not null, institution_id uuid not null,
 candidate_id uuid not null, state text not null check(state in ('running','completed','failed')),
 user_id uuid references auth.users(id), study_id uuid references public.student_studies(id),
 requested_by uuid references auth.users(id), updated_at timestamptz not null default now(),
 unique(mapping_id,candidate_id),foreign key(mapping_id,institution_id) references public.admission_import_mappings(id,institution_id)
);
create function public.stamp_admission_review() returns trigger language plpgsql set search_path='' as $$
begin new.reviewed_by=auth.uid();new.reviewed_at=now();select revision into new.mapping_revision from public.admission_import_mappings where id=new.mapping_id;return new;end; $$;
revoke execute on function public.stamp_admission_review() from public,anon,authenticated;
create trigger admission_review_actor before insert or update on public.admission_import_reviews for each row execute function public.stamp_admission_review();
create function public.check_admission_mapping() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_OP='UPDATE' then
  if row(new.institution_id,new.program_id,new.academic_year_id,new.source_school_id,new.source_program_id,new.source_year_id,new.candidate_year_id) is distinct from row(old.institution_id,old.program_id,old.academic_year_id,old.source_school_id,old.source_program_id,old.source_year_id,old.candidate_year_id) and exists(select 1 from public.admission_import_jobs where mapping_id=old.id) then raise exception 'Mapping already has jobs';end if;
  if to_jsonb(new)-'revision' is distinct from to_jsonb(old)-'revision' then new.revision=old.revision+1;else new.revision=old.revision;end if;
 else new.revision=1;end if;
 if new.enabled and not public.institution_email_allowed(new.institution_id,'check@'||new.domain) then raise exception 'Domain not allowed' using errcode='23514';end if;
 return new;
end; $$;
revoke execute on function public.check_admission_mapping() from public,anon,authenticated;
create trigger admission_mapping_domain before insert or update on public.admission_import_mappings for each row execute function public.check_admission_mapping();
do $$ declare t text;begin foreach t in array array['admission_import_mappings','admission_import_reviews'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy system_admin on public.%I for all to authenticated using(public.is_superadmin()) with check(public.is_superadmin())',t);
 execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 execute format('create trigger admission_audit after insert or update or delete on public.%I for each row execute function public.audit_identity_change()',t);
 end loop;end; $$;
alter table public.admission_import_jobs enable row level security;
create policy import_jobs_read on public.admission_import_jobs for select to authenticated using(public.is_superadmin());
grant select on public.admission_import_jobs to authenticated;
-- Cross-project calls are not a DB transaction. A claim prevents parallel password issuance.
create function public.claim_admission_import(mapping uuid,candidate uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare job uuid;inst uuid;begin
 if not public.is_superadmin() and coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden' using errcode='42501';end if;
 select institution_id into inst from public.admission_import_mappings where id=mapping and enabled;
 if inst is null then raise exception 'Mapping unavailable';end if;
 insert into public.admission_import_jobs(mapping_id,institution_id,candidate_id,state,requested_by)
 values(mapping,inst,candidate,'running',auth.uid())
 on conflict(mapping_id,candidate_id) do update set state='running',updated_at=now(),requested_by=auth.uid()
 where public.admission_import_jobs.state='failed' returning id into job;
 return job;
end; $$;
revoke execute on function public.claim_admission_import(uuid,uuid) from public,anon;
grant execute on function public.claim_admission_import(uuid,uuid) to authenticated,service_role;

-- SOURCE: 202611060001_first_enrollment.sql
-- First enrollment is performed in ISVU; it does not require a prior university record in e-Matica.
alter table public.admission_import_mappings
 add column mode text not null default 'recorded' check(mode in ('recorded','first')),
 alter column source_school_id drop not null,
 alter column source_program_id drop not null,
 alter column source_year_id drop not null,
 alter column candidate_year_id drop not null,
 add constraint recorded_admission_source check(mode='first' or (source_school_id is not null and source_program_id is not null and source_year_id is not null and candidate_year_id is not null));
create unique index first_admission_program_year on public.admission_import_mappings(institution_id,program_id,academic_year_id) where mode='first';
alter table public.admission_import_reviews alter column source_choice_id drop not null,
 add column admission_approved boolean not null default false;
create or replace function public.stamp_admission_review() returns trigger language plpgsql set search_path='' as $$
declare workflow text;
begin
 new.reviewed_by=auth.uid();new.reviewed_at=now();
 select revision,mode into new.mapping_revision,workflow from public.admission_import_mappings where id=new.mapping_id;
 if workflow='recorded' and new.source_choice_id is null then raise exception 'Accepted choice required';end if;
 if workflow='first' and new.source_student_id<>new.candidate_id then raise exception 'Source student mismatch';end if;
 return new;
end; $$;
create or replace function public.check_admission_mapping() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_OP='UPDATE' then
  if row(new.mode,new.institution_id,new.program_id,new.academic_year_id,new.source_school_id,new.source_program_id,new.source_year_id,new.candidate_year_id) is distinct from row(old.mode,old.institution_id,old.program_id,old.academic_year_id,old.source_school_id,old.source_program_id,old.source_year_id,old.candidate_year_id) and exists(select 1 from public.admission_import_jobs where mapping_id=old.id) then raise exception 'Mapping already has jobs';end if;
  if to_jsonb(new)-'revision' is distinct from to_jsonb(old)-'revision' then new.revision=old.revision+1;else new.revision=old.revision;end if;
 else new.revision=1;end if;
 if new.enabled and not public.institution_email_allowed(new.institution_id,'check@'||new.domain) then raise exception 'Domain not allowed' using errcode='23514';end if;
 return new;
end; $$;

-- SOURCE: 202611060002_exam_workflow.sql
-- Additive workflow. Existing terms retain their historical entry behaviour.
alter table public.exams add column workflow_status text not null default 'open'
 check(workflow_status in ('draft','open','registration_closed','in_progress','grading','locked'));
alter table public.exams add column legacy_workflow boolean not null default true;
alter table public.exams alter column workflow_status set default 'draft';
alter table public.exams alter column legacy_workflow set default false;
alter table public.grades alter column grade drop not null;
alter table public.grades add column outcome text not null default 'graded';
alter table public.grades add constraint grade_outcome_valid check(
 (outcome='graded' and grade is not null and grade between 1 and 5)
 or (outcome='absent' and grade is null));

create table public.exam_workflow_events (
 id uuid primary key default gen_random_uuid(),
 institution_id uuid not null,
 exam_id uuid not null,
 actor_id uuid not null references public.profiles(id),
 previous_status text not null,
 next_status text not null,
 reason text not null check(length(btrim(reason)) between 10 and 1000),
 occurred_at timestamptz not null default now(),
 foreign key(institution_id,exam_id) references public.exams(institution_id,id)
);
create index exam_workflow_events_term on public.exam_workflow_events(exam_id,occurred_at);
alter table public.exam_workflow_events enable row level security;
revoke all on public.exam_workflow_events from public,anon,authenticated;
grant select on public.exam_workflow_events to authenticated;
create policy exam_events_read on public.exam_workflow_events for select to authenticated
 using(public.exam_staff(institution_id,exam_id));

-- Lifecycle fields are changed exclusively through the authorized transition RPC.
revoke insert,update on public.exams from authenticated;
grant insert(institution_id,course_id,room_id,starts_at,registration_deadline,withdrawal_deadline,capacity,id),
 update(course_id,room_id,starts_at,registration_deadline,withdrawal_deadline,capacity)
 on public.exams to authenticated;

create function public.exam_lock_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if old.workflow_status='locked' then
  if TG_OP='DELETE' then raise exception 'Zaključani rok nije dopušteno izbrisati.'; end if;
  if (to_jsonb(new)-'workflow_status'-'legacy_workflow') is distinct from (to_jsonb(old)-'workflow_status'-'legacy_workflow')
   then raise exception 'Najprije otključajte ispitni rok uz obrazloženje.'; end if;
 end if;
 if TG_OP='DELETE' then return old; end if;
 return new;
end; $$;
create trigger exam_lock_guard before update or delete on public.exams
 for each row execute function public.exam_lock_guard();

create function public.transition_exam(target uuid, expected_status text, next_status text, reason text)
 returns void language plpgsql security definer set search_path='' as $$
declare e public.exams;
begin
 select * into e from public.exams where id=target for update;
 if not found or not public.course_staff(e.institution_id,e.course_id)
  then raise exception 'Nemate pravo upravljanja rokom.' using errcode='42501'; end if;
 if e.workflow_status<>expected_status then raise exception 'Stanje roka je promijenjeno. Osvježite prikaz.'; end if;
 if reason is null or length(btrim(reason)) not between 10 and 1000 then raise exception 'Navedite obrazloženje od 10 do 1000 znakova.'; end if;
 if e.workflow_status='locked' then
  if next_status<>'grading' or not public.academic_manager(e.institution_id)
   then raise exception 'Otključavanje je dopušteno samo administratoru ili referadi.' using errcode='42501'; end if;
 elsif not (
  (e.workflow_status='draft' and next_status='open') or
  (e.workflow_status='open' and next_status='registration_closed') or
  (e.workflow_status='registration_closed' and next_status='in_progress') or
  (e.workflow_status='in_progress' and next_status='grading') or
  (e.workflow_status='grading' and next_status='locked'))
  then raise exception 'Nedopušten prijelaz stanja roka.'; end if;
 if next_status='open' and e.registration_deadline<now() then raise exception 'Rok prijave je istekao. Uredite termin prije otvaranja.'; end if;
 if next_status in ('in_progress','grading','locked') and e.starts_at>now() then raise exception 'Ispit još nije održan.'; end if;
 if next_status='locked' and exists(
  select 1 from public.exam_registrations r where r.exam_id=e.id and r.status='registered'
  and not exists(select 1 from public.grades g where g.exam_id=e.id and g.student_id=r.student_id))
  then raise exception 'Za sve važeće prijave treba evidentirati ocjenu ili nedolazak.'; end if;
 update public.exams set workflow_status=next_status,legacy_workflow=false where id=e.id;
 insert into public.exam_workflow_events(institution_id,exam_id,actor_id,previous_status,next_status,reason)
 values(e.institution_id,e.id,auth.uid(),e.workflow_status,next_status,btrim(reason));
end; $$;

-- Serialize against transition_exam, including writes through service clients.
create function public.exam_result_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare e public.exams; exam uuid;
begin
 if TG_OP='DELETE' then exam=old.exam_id; else exam=new.exam_id; end if;
 if TG_OP='UPDATE' and (new.exam_id<>old.exam_id or new.student_id<>old.student_id or new.institution_id<>old.institution_id)
  then raise exception 'Identitet rezultata ne može se mijenjati.'; end if;
 select * into e from public.exams where id=exam for update;
 if e.workflow_status='locked' then raise exception 'Ispitni rok je zaključan.'; end if;
 if not (e.workflow_status='grading' or (e.legacy_workflow and e.workflow_status='open'))
  then raise exception 'Rok mora biti u obradi rezultata.'; end if;
 if e.starts_at>now() then raise exception 'Ispit još nije održan.'; end if;
 if TG_OP='DELETE' then return old; end if;
 if not exists(select 1 from public.exam_registrations r where r.exam_id=e.id and r.student_id=new.student_id and r.status='registered')
  then raise exception 'Student nije prijavljen na ispit.'; end if;
 return new;
end; $$;
create trigger exam_result_guard before insert or update or delete on public.grades
 for each row execute function public.exam_result_guard();

create or replace function public.register_exam(target uuid,cancel boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare e public.exams; existing_status text;
begin
 perform 1 from public.profiles where id=auth.uid() for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.enrolled(e.course_id) then raise exception 'Nemate pravo pristupa ispitu.' using errcode='42501'; end if;
 if (not cancel and e.workflow_status<>'open') or (cancel and e.workflow_status not in ('open','registration_closed'))
  then raise exception 'Stanje roka ne dopušta prijavu ili odjavu.'; end if;
 if exists(select 1 from public.grades where exam_id=e.id and student_id=auth.uid()) then raise exception 'Ispit je već obrađen.'; end if;
 if cancel then
  if now()>e.withdrawal_deadline then raise exception 'Rok za odjavu je istekao.'; end if;
  update public.exam_registrations set status='cancelled' where exam_id=e.id and student_id=auth.uid() and status='registered';
 else
  if now()>e.registration_deadline then raise exception 'Rok za prijavu je istekao.'; end if;
  if exists(select 1 from public.grades g join public.exams x on x.id=g.exam_id join public.courses c on c.id=x.course_id join public.courses own on own.id=e.course_id where g.student_id=auth.uid() and g.grade>1 and c.institution_id=e.institution_id and c.code=own.code) then raise exception 'Kolegij je već položen.'; end if;
  select status into existing_status from public.exam_registrations where exam_id=e.id and student_id=auth.uid();
  if existing_status='registered' then return; end if;
  if (select count(*) from public.exam_registrations where exam_id=e.id and status='registered')>=e.capacity then raise exception 'Ispitni rok je popunjen.'; end if;
  insert into public.exam_registrations(institution_id,exam_id,student_id) values(e.institution_id,e.id,auth.uid()) on conflict(institution_id,exam_id,student_id) do update set status='registered',registered_at=now();
 end if;
end; $$;

create or replace function public.record_grade(target uuid,student uuid,result integer,note text default '') returns void language plpgsql security definer set search_path='' as $$
declare e public.exams;
begin
 perform 1 from public.profiles where id=student for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.course_staff(e.institution_id,e.course_id) then raise exception 'Nemate pravo ocjenjivanja.' using errcode='42501'; end if;
 if result is null or result not between 1 and 5 then raise exception 'Ocjena mora biti od 1 do 5.'; end if;
 if e.starts_at>now() then raise exception 'Ispit još nije održan.'; end if;
 if not exists(select 1 from public.exam_registrations r where r.exam_id=e.id and r.student_id=student and r.status='registered') then raise exception 'Student nije prijavljen na ispit.'; end if;
 insert into public.grades(institution_id,exam_id,student_id,grade,outcome,feedback,graded_by) values(e.institution_id,e.id,student,result,'graded',note,auth.uid()) on conflict(institution_id,exam_id,student_id) do update set grade=result,outcome='graded',feedback=note,graded_by=auth.uid(),graded_at=now();
 if result>1 then
  update public.exam_registrations r set status='cancelled' from public.exams other_exam,public.courses other_course,public.courses own_course where r.exam_id=other_exam.id and other_exam.course_id=other_course.id and own_course.id=e.course_id and other_course.institution_id=e.institution_id and other_course.code=own_course.code and r.student_id=student and r.status='registered' and other_exam.starts_at>now() and other_exam.id<>e.id and other_exam.workflow_status<>'locked';
 end if;
end; $$;

create function public.record_exam_absence(target uuid,student uuid,note text default '') returns void language plpgsql security definer set search_path='' as $$
declare e public.exams;
begin
 perform 1 from public.profiles where id=student for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.course_staff(e.institution_id,e.course_id) then raise exception 'Nemate pravo obrade rezultata.' using errcode='42501'; end if;
 insert into public.grades(institution_id,exam_id,student_id,grade,outcome,feedback,graded_by)
 values(e.institution_id,e.id,student,null,'absent',note,auth.uid())
 on conflict(institution_id,exam_id,student_id) do update set grade=null,outcome='absent',feedback=note,graded_by=auth.uid(),graded_at=now();
end; $$;

revoke execute on function public.exam_lock_guard(),public.exam_result_guard() from public,anon,authenticated;
revoke execute on function public.transition_exam(uuid,text,text,text),public.record_exam_absence(uuid,uuid,text) from public,anon;
grant execute on function public.transition_exam(uuid,text,text,text),public.record_exam_absence(uuid,uuid,text) to authenticated;

-- SOURCE: 202611060003_enrollment_completion.sql
-- Administrative completion is distinct from active/completed/paused study status.
alter table public.student_studies
 add column completion_status text not null default 'legacy_unverified'
 check(completion_status in ('legacy_unverified','draft','pending_verification','completed','cancelled')),
 add column identity_verified boolean not null default false,
 add column documents_verified boolean not null default false,
 add column curriculum_verified boolean not null default false,
 add column financing_verified boolean not null default false,
 add column completion_revision integer not null default 0,
 add column completed_by uuid references public.profiles(id),
 add column completed_at timestamptz;
alter table public.student_studies alter column completion_status set default 'draft';
alter table public.student_studies add constraint completion_evidence check(
 completion_status<>'completed' or (identity_verified and documents_verified and curriculum_verified and financing_verified and completed_by is not null and completed_at is not null));

create table public.enrollment_completion_events (
 id uuid primary key default gen_random_uuid(),
 institution_id uuid not null,
 study_id uuid not null,
 student_id uuid not null,
 actor_id uuid not null references public.profiles(id),
 previous_status text not null,
 next_status text not null,
 identity_verified boolean not null,
 documents_verified boolean not null,
 curriculum_verified boolean not null,
 financing_verified boolean not null,
 reason text not null check(length(btrim(reason)) between 10 and 1000),
 occurred_at timestamptz not null default now(),
 foreign key(institution_id,study_id,student_id) references public.student_studies(institution_id,id,student_id)
);
create index enrollment_completion_events_study on public.enrollment_completion_events(study_id,occurred_at);
alter table public.enrollment_completion_events enable row level security;
revoke all on public.enrollment_completion_events from public,anon,authenticated;
grant select on public.enrollment_completion_events to authenticated;
create policy enrollment_events_read on public.enrollment_completion_events for select to authenticated
 using(public.academic_manager(institution_id));
revoke insert,update on public.student_studies from authenticated;
grant insert(id,institution_id,student_id,program_id,academic_year_id,study_year,student_number,status),
 update(student_id,program_id,academic_year_id,study_year,student_number,status) on public.student_studies to authenticated;

create function public.enrollment_completion_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare s public.student_studies;
begin
 if TG_TABLE_NAME='student_studies' then
  if TG_OP='DELETE' then
   if old.completion_status='completed' then raise exception 'Dovršeni upis nije dopušteno izbrisati.'; end if;
   return old;
  end if;
  perform 1 from public.profiles where id=new.student_id for update;
  if TG_OP='UPDATE' and old.completion_status='completed' and
   row(new.student_id,new.program_id,new.academic_year_id,new.study_year,new.student_number)
   is distinct from row(old.student_id,old.program_id,old.academic_year_id,old.study_year,old.student_number)
   then raise exception 'Najprije ponovno otvorite provjeru upisa.'; end if;
  if TG_OP='INSERT' or (TG_OP='UPDATE' and row(new.student_id,new.program_id,new.academic_year_id) is distinct from row(old.student_id,old.program_id,old.academic_year_id)) then
   if exists(select 1 from public.student_studies previous
    join public.academic_years previous_year on previous_year.id=previous.academic_year_id
    join public.academic_years next_year on next_year.id=new.academic_year_id
    where previous.student_id=new.student_id and previous.institution_id=new.institution_id and previous.program_id=new.program_id
    and previous_year.starts_on<next_year.starts_on and previous.completion_status not in ('completed','cancelled'))
    then raise exception 'Prethodni upis nije administrativno dovršen.'; end if;
  end if;
  return new;
 end if;
 -- Lock all affected study rows in a stable order when moving a course enrollment.
 if TG_OP<>'INSERT' then
  perform 1 from public.profiles where id=old.student_id for update;
 end if;
 if TG_OP<>'DELETE' then
  perform 1 from public.profiles where id=new.student_id for update;
 end if;
 for s in select * from public.student_studies where
  id=case when TG_OP='DELETE' then old.study_id else new.study_id end
  or (TG_OP='UPDATE' and id=old.study_id) order by id for update
 loop
  if s.completion_status in ('completed','cancelled') then raise exception 'Najprije ponovno otvorite provjeru upisa.'; end if;
 end loop;
 if TG_OP='DELETE' then return old; end if;
 return new;
end; $$;
create trigger enrollment_completion_guard before insert or update or delete on public.student_studies
 for each row execute function public.enrollment_completion_guard();
create trigger enrollment_completion_guard before insert or update or delete on public.course_enrollments
 for each row execute function public.enrollment_completion_guard();

create function public.complete_enrollment(target uuid,expected_revision integer,next_status text,
 identity_checked boolean,documents_checked boolean,curriculum_checked boolean,financing_checked boolean,reason text)
 returns void language plpgsql security definer set search_path='' as $$
declare s public.student_studies;
begin
 select * into s from public.student_studies where id=target;
 if not found or not public.academic_manager(s.institution_id) then raise exception 'Nemate pravo provjere upisa.' using errcode='42501'; end if;
 perform 1 from public.profiles where id=s.student_id for update;
 select * into s from public.student_studies where id=target for update;
 if s.completion_revision<>expected_revision then raise exception 'Upis je promijenjen. Osvježite prikaz.'; end if;
 if reason is null or length(btrim(reason)) not between 10 and 1000 then raise exception 'Navedite obrazloženje od 10 do 1000 znakova.'; end if;
 if not ((s.completion_status in ('legacy_unverified','draft','completed','cancelled') and next_status='pending_verification')
  or (s.completion_status='pending_verification' and next_status in ('pending_verification','completed','cancelled'))
  or (s.completion_status='draft' and next_status='cancelled')) then raise exception 'Nedopušten prijelaz stanja upisa.'; end if;
 if next_status='completed' then
  if s.status<>'active' then raise exception 'Za dovršenje je potreban aktivan studij.'; end if;
  if not(coalesce(identity_checked,false) and coalesce(documents_checked,false) and coalesce(curriculum_checked,false) and coalesce(financing_checked,false))
   then raise exception 'Provjerite identitet, dokumente, predmetnik i financiranje.'; end if;
  if not exists(select 1 from public.course_enrollments where study_id=s.id)
   then raise exception 'Upis nema nijedan kolegij. Najprije sastavite upisni list.'; end if;
 end if;
 update public.student_studies set completion_status=next_status,
  identity_verified=coalesce(identity_checked,false),documents_verified=coalesce(documents_checked,false),
  curriculum_verified=coalesce(curriculum_checked,false),financing_verified=coalesce(financing_checked,false),
  completed_by=case when next_status='completed' then auth.uid() else null end,
  completed_at=case when next_status='completed' then now() else null end,
  completion_revision=s.completion_revision+1 where id=s.id;
 insert into public.enrollment_completion_events(institution_id,study_id,student_id,actor_id,previous_status,next_status,
 identity_verified,documents_verified,curriculum_verified,financing_verified,reason)
 values(s.institution_id,s.id,s.student_id,auth.uid(),s.completion_status,next_status,
 coalesce(identity_checked,false),coalesce(documents_checked,false),coalesce(curriculum_checked,false),coalesce(financing_checked,false),btrim(reason));
end; $$;

-- Historical enrollments keep their previous exam access until explicitly reviewed.
-- They are NOT displayed or recorded as completed and cannot be used to open a later year.
create function public.exam_enrollment_complete(target uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.course_enrollments e join public.student_studies s on s.id=e.study_id
 where e.course_id=target and e.student_id=auth.uid() and s.status='active' and s.completion_status in ('completed','legacy_unverified'));
$$;
revoke execute on function public.enrollment_completion_guard() from public,anon,authenticated;
revoke execute on function public.complete_enrollment(uuid,integer,text,boolean,boolean,boolean,boolean,text),public.exam_enrollment_complete(uuid) from public,anon;
grant execute on function public.complete_enrollment(uuid,integer,text,boolean,boolean,boolean,boolean,text),public.exam_enrollment_complete(uuid) to authenticated;

create or replace function public.register_exam(target uuid,cancel boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare e public.exams; existing_status text;
begin
 perform 1 from public.profiles where id=auth.uid() for update;
 select * into e from public.exams where id=target for update;
 if not found or not public.enrolled(e.course_id) then raise exception 'Nemate pravo pristupa ispitu.' using errcode='42501'; end if;
 if (not cancel and e.workflow_status<>'open') or (cancel and e.workflow_status not in ('open','registration_closed'))
  then raise exception 'Stanje roka ne dopušta prijavu ili odjavu.'; end if;
 if not cancel and not public.exam_enrollment_complete(e.course_id) then raise exception 'Upis nije administrativno dovršen. Obratite se referadi.'; end if;
 if exists(select 1 from public.grades where exam_id=e.id and student_id=auth.uid()) then raise exception 'Ispit je već obrađen.'; end if;
 if cancel then
  if now()>e.withdrawal_deadline then raise exception 'Rok za odjavu je istekao.'; end if;
  update public.exam_registrations set status='cancelled' where exam_id=e.id and student_id=auth.uid() and status='registered';
 else
  if now()>e.registration_deadline then raise exception 'Rok za prijavu je istekao.'; end if;
  if exists(select 1 from public.grades g join public.exams x on x.id=g.exam_id join public.courses c on c.id=x.course_id join public.courses own on own.id=e.course_id where g.student_id=auth.uid() and g.grade>1 and c.institution_id=e.institution_id and c.code=own.code) then raise exception 'Kolegij je već položen.'; end if;
  select status into existing_status from public.exam_registrations where exam_id=e.id and student_id=auth.uid();
  if existing_status='registered' then return; end if;
  if (select count(*) from public.exam_registrations where exam_id=e.id and status='registered')>=e.capacity then raise exception 'Ispitni rok je popunjen.'; end if;
  insert into public.exam_registrations(institution_id,exam_id,student_id) values(e.institution_id,e.id,auth.uid()) on conflict(institution_id,exam_id,student_id) do update set status='registered',registered_at=now();
 end if;
end; $$;

-- SOURCE: 202611060004_grade_history.sql
-- Restricted domain history; never place grades or feedback in the general audit log.
create table public.exam_grade_events (
 id uuid primary key default gen_random_uuid(),
 institution_id uuid not null,
 exam_id uuid not null,
 student_id uuid not null references public.profiles(id),
 actor_id uuid not null references public.profiles(id),
 action text not null check(action in ('BASELINE','INSERT','UPDATE','DELETE')),
 previous_grade integer check(previous_grade between 1 and 5),
 next_grade integer check(next_grade between 1 and 5),
 previous_outcome text check(previous_outcome in ('graded','absent')),
 next_outcome text check(next_outcome in ('graded','absent')),
 workflow_event_id uuid references public.exam_workflow_events(id),
 occurred_at timestamptz not null default now(),
 foreign key(institution_id,exam_id) references public.exams(institution_id,id)
);
create index exam_grade_events_student on public.exam_grade_events(institution_id,student_id,occurred_at);
alter table public.exam_grade_events enable row level security;
revoke all on public.exam_grade_events from public,anon,authenticated;
grant select on public.exam_grade_events to authenticated;
create policy grade_events_read on public.exam_grade_events for select to authenticated
 using((student_id=auth.uid() and public.has_role(institution_id)) or public.exam_staff(institution_id,exam_id));
-- This records only the known current state, without inventing earlier revisions.
insert into public.exam_grade_events(institution_id,exam_id,student_id,actor_id,action,next_grade,next_outcome,occurred_at)
 select institution_id,exam_id,student_id,graded_by,'BASELINE',grade,outcome,graded_at from public.grades;
create function public.record_exam_grade_event() returns trigger language plpgsql security definer set search_path='' as $$
declare g public.grades; linked_event uuid;
begin
 if TG_OP='DELETE' then g=old; else g=new; end if;
 select id into linked_event from public.exam_workflow_events where exam_id=g.exam_id order by occurred_at desc,id desc limit 1;
 insert into public.exam_grade_events(institution_id,exam_id,student_id,actor_id,action,
 previous_grade,next_grade,previous_outcome,next_outcome,workflow_event_id)
 values(g.institution_id,g.exam_id,g.student_id,coalesce(auth.uid(),g.graded_by),TG_OP,
 case when TG_OP<>'INSERT' then old.grade end,case when TG_OP<>'DELETE' then new.grade end,
 case when TG_OP<>'INSERT' then old.outcome end,case when TG_OP<>'DELETE' then new.outcome end,linked_event);
 if TG_OP='DELETE' then return old; end if;
 return new;
end; $$;
create trigger exam_grade_history after insert or update or delete on public.grades
 for each row execute function public.record_exam_grade_event();
revoke execute on function public.record_exam_grade_event() from public,anon,authenticated;

-- Unpublished drafts are visible to authorized staff only, including direct API reads.
drop policy exams_read on public.exams;
create policy exams_read on public.exams for select to authenticated using(
 public.course_staff(institution_id,course_id)
 or (workflow_status<>'draft' and public.enrolled(course_id))
 or (public.has_role(institution_id) and exists(select 1 from public.exam_registrations r where r.exam_id=exams.id and r.student_id=auth.uid())));

-- SOURCE: 202611060005_registrar_workbench.sql
-- Registrar-managed admissions, official dossiers and annual records.
-- Self-reported student_reports remain separate from verified institutional data.
create table public.student_records (
 id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id),
 student_id uuid not null references public.profiles(id),
 local_number text not null default ('LOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16))),
 legal_name text not null check(length(btrim(legal_name)) between 2 and 200), birth_date date,
 citizenship text not null default '' check(length(citizenship)<=100),
 jmbag text not null default '' check(jmbag='' or jmbag ~ '^[0-9]{10}$'),
 oib text not null default '' check(oib='' or oib ~ '^[0-9]{11}$'),
 identity_reference text not null default '' check(length(identity_reference)<=300),
 revision integer not null default 1, updated_by uuid references public.profiles(id),updated_at timestamptz not null default now(),
 unique(institution_id,student_id),unique(institution_id,local_number),
 check((jmbag='' and oib='') or length(btrim(identity_reference))>=3)
);
create unique index institutional_jmbag on public.student_records(institution_id,jmbag) where jmbag<>'';
create unique index institutional_oib on public.student_records(institution_id,oib) where oib<>'';
create table public.student_year_records (
 id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),
 student_id uuid not null references public.profiles(id),academic_year_id uuid not null,
 details jsonb not null default '{}' check(jsonb_typeof(details)='object' and octet_length(details::text)<=12000),
 revision integer not null default 1,updated_by uuid references public.profiles(id),updated_at timestamptz not null default now(),
 unique(institution_id,student_id,academic_year_id),
 foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id)
);
create table public.registrar_enrollment_cases (
 id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),
 student_id uuid not null references public.profiles(id),program_id uuid not null,academic_year_id uuid not null,
 kind text not null check(kind in ('first_matura','first_selection','next_year','repeat','transfer','parallel','postgraduate','continuation')),
 study_year integer not null check(study_year between 1 and 8),mode text not null check(mode in ('full_time','part_time')),
 financing text not null check(length(btrim(financing)) between 2 and 300),
 admission_number text not null default '' check(length(admission_number)<=100),
 decision_reference text not null check(length(btrim(decision_reference)) between 3 and 300),
 source_institution text not null default '' check(length(source_institution)<=300),
 previous_study_id uuid,winter_semester integer check(winter_semester between 1 and 16),summer_semester integer check(summer_semester between 1 and 16),
 documents_verified boolean not null default false,conditions_verified boolean not null default false,
 matura_verified boolean not null default false,qualification_verified boolean not null default false,
 state text not null default 'draft' check(state in ('draft','approved','enrolled','cancelled')),
 revision integer not null default 1,study_id uuid,
 created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),
 unique(institution_id,student_id,program_id,academic_year_id),unique(institution_id,id),
 foreign key(institution_id,program_id) references public.study_programs(institution_id,id),
 foreign key(institution_id,academic_year_id) references public.academic_years(institution_id,id),
 foreign key(institution_id,previous_study_id,student_id) references public.student_studies(institution_id,id,student_id),
 foreign key(institution_id,study_id,student_id) references public.student_studies(institution_id,id,student_id)
);
create table public.registrar_case_events (
 id uuid primary key default gen_random_uuid(),institution_id uuid not null,case_id uuid not null,
 actor_id uuid not null references public.profiles(id),action text not null,reason text not null check(length(btrim(reason)) between 10 and 1000),
 occurred_at timestamptz not null default now(),foreign key(institution_id,case_id) references public.registrar_enrollment_cases(institution_id,id)
);
create index registrar_cases_lookup on public.registrar_enrollment_cases(institution_id,state,academic_year_id);
create index registrar_case_history on public.registrar_case_events(case_id,occurred_at);
do $$ declare t text;begin
 foreach t in array array['student_records','student_year_records','registrar_enrollment_cases','registrar_case_events'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy registrar_read on public.%I for select to authenticated using(public.academic_manager(institution_id))',t);
  execute format('create trigger registrar_audit after insert or update or delete on public.%I for each row execute function public.audit_identity_change()',t);
 end loop;
end $$;
create policy student_own_record on public.student_records for select to authenticated using(student_id=auth.uid() and public.has_role(institution_id));
create policy student_own_year on public.student_year_records for select to authenticated using(student_id=auth.uid() and public.has_role(institution_id));
-- Case decisions and internal references are staff-only. Students see their resulting studies and verified annual records.

-- Registrars need a roster before the first study exists; this does not allow role changes.
create policy registrar_student_roster on public.memberships for select to authenticated using(role='student' and public.academic_manager(institution_id));
create policy registrar_student_names on public.profiles for select to authenticated using(
 exists(select 1 from public.memberships m where m.user_id=profiles.id and m.role='student' and public.academic_manager(m.institution_id)));

create function public.registrar_save_record(inst uuid, target uuid, expected_revision integer, data jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare r public.student_records;
begin
 if not public.academic_manager(inst) or not public.is_institution_student(inst,target) then raise exception 'Forbidden' using errcode='42501';end if;
 perform 1 from public.profiles where id=target for update;
 select * into r from public.student_records where institution_id=inst and student_id=target for update;
 if coalesce(r.revision,0)<>expected_revision then raise exception 'REGISTRAR_STALE';end if;
 insert into public.student_records(institution_id,student_id,legal_name,birth_date,citizenship,jmbag,oib,identity_reference,updated_by)
 values(inst,target,btrim(data->>'legal_name'),nullif(data->>'birth_date','')::date,coalesce(data->>'citizenship',''),coalesce(data->>'jmbag',''),coalesce(data->>'oib',''),coalesce(data->>'identity_reference',''),auth.uid())
 on conflict(institution_id,student_id) do update set legal_name=excluded.legal_name,birth_date=excluded.birth_date,citizenship=excluded.citizenship,
 jmbag=excluded.jmbag,oib=excluded.oib,identity_reference=excluded.identity_reference,revision=public.student_records.revision+1,updated_by=auth.uid(),updated_at=now();
end; $$;
create function public.registrar_save_year(inst uuid,target uuid,year_id uuid,expected_revision integer,data jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare r public.student_year_records;
begin
 if not public.academic_manager(inst) or not public.is_institution_student(inst,target) then raise exception 'Forbidden' using errcode='42501';end if;
 perform 1 from public.profiles where id=target for update;
 if jsonb_typeof(data)<>'object' or exists(select 1 from jsonb_each(data) e where jsonb_typeof(e.value)<>'string' or length(e.value#>>'{}')>300
  or e.key not in ('residence_country','residence_city','residence_postcode','residence_address','residence_confirmation_date','housing_city','housing_address','housing_status','health_insurance','marital_status','scholarship','mother_education','mother_occupation','mother_employment','father_education','father_occupation','father_employment','supporter','supporter_occupation','supporter_employment')) then raise exception 'REGISTRAR_CHECKS';end if;
 if coalesce(data->>'residence_confirmation_date','')<>'' then perform (data->>'residence_confirmation_date')::date;end if;
 if not exists(select 1 from public.student_studies where institution_id=inst and student_id=target and academic_year_id=year_id) then raise exception 'Godišnji upis ne postoji.';end if;
 select * into r from public.student_year_records where institution_id=inst and student_id=target and academic_year_id=year_id for update;
 if coalesce(r.revision,0)<>expected_revision then raise exception 'REGISTRAR_STALE';end if;
 insert into public.student_year_records(institution_id,student_id,academic_year_id,details,updated_by) values(inst,target,year_id,data,auth.uid())
 on conflict(institution_id,student_id,academic_year_id) do update set details=excluded.details,revision=public.student_year_records.revision+1,updated_by=auth.uid(),updated_at=now();
end; $$;

create function public.registrar_case_integrity() returns trigger language plpgsql security definer set search_path='' as $$
declare p public.study_programs;previous public.student_studies;prev_start date;next_start date;
begin
 select * into p from public.study_programs where id=new.program_id and institution_id=new.institution_id;
 if not found or not public.is_institution_student(new.institution_id,new.student_id) then raise exception 'Forbidden' using errcode='42501';end if;
 if new.study_year>p.duration_years then raise exception 'REGISTRAR_PREVIOUS';end if;
 if new.kind in ('first_matura','first_selection') and new.study_year<>1 then raise exception 'REGISTRAR_PREVIOUS';end if;
 if new.kind='postgraduate' and (greatest(coalesce(new.winter_semester,0),coalesce(new.summer_semester,0))>p.duration_years*2 or (new.winter_semester is not null and new.winter_semester=new.summer_semester) or p.degree<>'Poslijediplomski' or (new.winter_semester is null and new.summer_semester is null)
  or new.study_year<>ceil(least(coalesce(new.winter_semester,99),coalesce(new.summer_semester,99))/2.0)) then raise exception 'REGISTRAR_POSTGRADUATE';end if;
 if p.degree='Poslijediplomski' and new.kind<>'postgraduate' then raise exception 'REGISTRAR_POSTGRADUATE';end if;
 if new.kind='transfer' and length(btrim(new.source_institution))<2 then raise exception 'REGISTRAR_CHECKS';end if;
 if new.kind in ('next_year','repeat','continuation') then
  select * into previous from public.student_studies where id=new.previous_study_id and institution_id=new.institution_id and student_id=new.student_id and program_id=new.program_id;
  if not found or previous.completion_status<>'completed' then raise exception 'REGISTRAR_PREVIOUS';end if;
  select starts_on into prev_start from public.academic_years where id=previous.academic_year_id;
  select starts_on into next_start from public.academic_years where id=new.academic_year_id;
  if next_start<=prev_start or (new.kind='next_year' and new.study_year<>previous.study_year+1)
   or (new.kind='repeat' and new.study_year<>previous.study_year) then raise exception 'REGISTRAR_PREVIOUS';end if;
 end if;
 if new.state in ('approved','enrolled') and (not new.documents_verified or not new.conditions_verified
  or (new.kind='first_matura' and not new.matura_verified) or (new.kind in ('postgraduate','first_selection') and not new.qualification_verified)) then raise exception 'REGISTRAR_CHECKS';end if;
 return new;
end; $$;
create trigger registrar_case_integrity before insert or update on public.registrar_enrollment_cases for each row execute function public.registrar_case_integrity();

create function public.registrar_save_case(inst uuid,target uuid,expected_revision integer,data jsonb,reason text) returns uuid
language plpgsql security definer set search_path='' as $$
declare r public.registrar_enrollment_cases;result uuid;student uuid;
begin
 if not public.academic_manager(inst) then raise exception 'Forbidden' using errcode='42501';end if;
 student=(data->>'student_id')::uuid;
 if reason is null or length(btrim(reason)) not between 10 and 1000 then raise exception 'REGISTRAR_CHECKS';end if;
 perform 1 from public.profiles where id=student for update;
 if target is not null then
  select * into r from public.registrar_enrollment_cases where id=target and institution_id=inst for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if r.state<>'draft' or r.revision<>expected_revision then raise exception 'REGISTRAR_STALE';end if;
  if row(r.student_id,r.program_id,r.academic_year_id) is distinct from row(student,(data->>'program_id')::uuid,(data->>'academic_year_id')::uuid)
   then raise exception 'REGISTRAR_EXISTING';end if;
 elsif expected_revision<>0 then raise exception 'REGISTRAR_STALE';end if;
 insert into public.registrar_enrollment_cases(id,institution_id,student_id,program_id,academic_year_id,kind,study_year,mode,financing,admission_number,decision_reference,source_institution,previous_study_id,winter_semester,summer_semester,created_by)
 values(coalesce(target,gen_random_uuid()),inst,student,(data->>'program_id')::uuid,(data->>'academic_year_id')::uuid,data->>'kind',(data->>'study_year')::integer,data->>'mode',data->>'financing',coalesce(data->>'admission_number',''),data->>'decision_reference',coalesce(data->>'source_institution',''),nullif(data->>'previous_study_id','')::uuid,nullif(data->>'winter_semester','')::integer,nullif(data->>'summer_semester','')::integer,auth.uid())
 on conflict(id) do update set kind=excluded.kind,study_year=excluded.study_year,mode=excluded.mode,financing=excluded.financing,
 admission_number=excluded.admission_number,decision_reference=excluded.decision_reference,source_institution=excluded.source_institution,previous_study_id=excluded.previous_study_id,winter_semester=excluded.winter_semester,summer_semester=excluded.summer_semester,
 revision=public.registrar_enrollment_cases.revision+1,updated_at=now() returning id into result;
 insert into public.registrar_case_events(institution_id,case_id,actor_id,action,reason) values(inst,result,auth.uid(),case when target is null then 'created' else 'edited' end,btrim(reason));
 return result;
end; $$;

create function public.registrar_decide_case(target uuid,expected_revision integer,next_state text,checks jsonb,reason text) returns void
language plpgsql security definer set search_path='' as $$
declare r public.registrar_enrollment_cases;
begin
 select * into r from public.registrar_enrollment_cases where id=target;
 if not found or not public.academic_manager(r.institution_id) then raise exception 'Forbidden' using errcode='42501';end if;
 perform 1 from public.profiles where id=r.student_id for update;
 select * into r from public.registrar_enrollment_cases where id=target for update;
 if r.revision<>expected_revision then raise exception 'REGISTRAR_STALE';end if;
 if reason is null or length(btrim(reason)) not between 10 and 1000 then raise exception 'REGISTRAR_CHECKS';end if;
 if not((r.state='draft' and next_state in ('approved','cancelled')) or (r.state='approved' and next_state in ('draft','cancelled')) or (r.state='cancelled' and next_state='draft')) then raise exception 'REGISTRAR_STALE';end if;
 update public.registrar_enrollment_cases set state=next_state,
 documents_verified=coalesce((checks->>'documents_verified')::boolean,false),conditions_verified=coalesce((checks->>'conditions_verified')::boolean,false),
 matura_verified=coalesce((checks->>'matura_verified')::boolean,false),qualification_verified=coalesce((checks->>'qualification_verified')::boolean,false),revision=r.revision+1,updated_at=now() where id=r.id;
 insert into public.registrar_case_events(institution_id,case_id,actor_id,action,reason) values(r.institution_id,r.id,auth.uid(),next_state,btrim(reason));
end; $$;

create function public.registrar_enroll_case(target uuid,expected_revision integer,selected_courses uuid[],reason text) returns uuid
language plpgsql security definer set search_path='' as $$
declare r public.registrar_enrollment_cases;s public.student_studies;rec public.student_records;cid uuid;result uuid;
begin
 select * into r from public.registrar_enrollment_cases where id=target;
 if not found or not public.academic_manager(r.institution_id) then raise exception 'Forbidden' using errcode='42501';end if;
 perform 1 from public.profiles where id=r.student_id for update;
 select * into r from public.registrar_enrollment_cases where id=target for update;
 if r.state<>'approved' or r.revision<>expected_revision then raise exception 'REGISTRAR_STALE';end if;
 if reason is null or length(btrim(reason)) not between 10 and 1000 then raise exception 'REGISTRAR_CHECKS';end if;
 if coalesce(cardinality(selected_courses),0) not between 1 and 100 or cardinality(selected_courses)<>(select count(distinct x) from unnest(selected_courses) x) then raise exception 'REGISTRAR_COURSES';end if;
 -- Validate the entire batch before inserting any course or study.
 if exists(select 1 from unnest(selected_courses) x left join public.courses c on c.id=x
  left join public.semesters sem on sem.id=c.semester_id
  where c.id is null or c.institution_id<>r.institution_id or c.program_id<>r.program_id or sem.academic_year_id<>r.academic_year_id)
  then raise exception 'REGISTRAR_COURSES';end if;
 if not exists(select 1 from public.student_records where institution_id=r.institution_id and student_id=r.student_id) and not exists(select 1 from public.profiles where id=r.student_id and length(btrim(full_name))>=2) then raise exception 'REGISTRAR_IDENTITY';end if;
 insert into public.student_records(institution_id,student_id,legal_name,updated_by)
 select r.institution_id,r.student_id,coalesce(nullif(btrim(full_name),''),'Student'),auth.uid() from public.profiles where id=r.student_id on conflict(institution_id,student_id) do nothing;
 select * into rec from public.student_records where institution_id=r.institution_id and student_id=r.student_id;
 select * into s from public.student_studies where institution_id=r.institution_id and student_id=r.student_id and program_id=r.program_id and academic_year_id=r.academic_year_id for update;
 if found then
  if s.completion_status not in ('draft','pending_verification') or s.study_year<>r.study_year or s.status<>'active' then raise exception 'REGISTRAR_EXISTING';end if;
  result=s.id;
 else
  insert into public.student_studies(institution_id,student_id,program_id,academic_year_id,study_year,student_number,status)
  values(r.institution_id,r.student_id,r.program_id,r.academic_year_id,r.study_year,rec.local_number,'active') returning id into result;
 end if;
 foreach cid in array selected_courses loop
  insert into public.course_enrollments(institution_id,study_id,course_id,student_id) values(r.institution_id,result,cid,r.student_id) on conflict(institution_id,course_id,student_id) do nothing;
 end loop;
 insert into public.student_year_records(institution_id,student_id,academic_year_id,updated_by) values(r.institution_id,r.student_id,r.academic_year_id,auth.uid()) on conflict(institution_id,student_id,academic_year_id) do nothing;
 update public.registrar_enrollment_cases set state='enrolled',study_id=result,revision=r.revision+1,updated_at=now() where id=r.id;
 insert into public.registrar_case_events(institution_id,case_id,actor_id,action,reason) values(r.institution_id,r.id,auth.uid(),'enrolled',btrim(reason));
 return result;
end; $$;

revoke execute on function public.registrar_case_integrity() from public,anon,authenticated;
revoke execute on function public.registrar_save_record(uuid,uuid,integer,jsonb),public.registrar_save_year(uuid,uuid,uuid,integer,jsonb),public.registrar_save_case(uuid,uuid,integer,jsonb,text),public.registrar_decide_case(uuid,integer,text,jsonb,text),public.registrar_enroll_case(uuid,integer,uuid[],text) from public,anon;
grant execute on function public.registrar_save_record(uuid,uuid,integer,jsonb),public.registrar_save_year(uuid,uuid,uuid,integer,jsonb),public.registrar_save_case(uuid,uuid,integer,jsonb,text),public.registrar_decide_case(uuid,integer,text,jsonb,text),public.registrar_enroll_case(uuid,integer,uuid[],text) to authenticated;

-- Source credentials remain server-side; actual enrollment is available to scoped registrar staff.
do $$ declare t text;begin foreach t in array array['admission_import_mappings','admission_import_reviews'] loop
 execute format('drop policy system_admin on public.%I',t);
 execute format('create policy admission_staff on public.%I for all to authenticated using(public.academic_manager(institution_id)) with check(public.academic_manager(institution_id))',t);
end loop;end $$;
drop policy import_jobs_read on public.admission_import_jobs;
create policy import_jobs_read on public.admission_import_jobs for select to authenticated using(public.academic_manager(institution_id));
create or replace function public.claim_admission_import(mapping uuid,candidate uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare job uuid;inst uuid;begin
 select institution_id into inst from public.admission_import_mappings where id=mapping and enabled;
 if inst is null or (not public.academic_manager(inst) and coalesce(auth.jwt()->>'role','')<>'service_role') then raise exception 'Forbidden' using errcode='42501';end if;
 insert into public.admission_import_jobs(mapping_id,institution_id,candidate_id,state,requested_by)
 values(mapping,inst,candidate,'running',auth.uid())
 on conflict(mapping_id,candidate_id) do update set state='running',updated_at=now(),requested_by=auth.uid()
 where public.admission_import_jobs.state='failed' returning id into job;
 return job;
end; $$;

-- Registrar can onboard students on approved institution domains, never staff roles.
create policy registrar_student_invites_read on public.registration_invites for select to authenticated
 using(role='student' and public.academic_manager(institution_id));
create policy registrar_student_invites_create on public.registration_invites for insert to authenticated
 with check(role='student' and created_by=auth.uid() and public.academic_manager(institution_id));
create or replace function public.claim_pending_credentials(invite_id uuid)
returns table(email text, institution_id uuid, existing_user_id uuid)
language plpgsql security definer set search_path='' as $$
declare invitation public.registration_invites; auth_user auth.users;
begin
 select * into invitation from public.registration_invites v where v.id=invite_id for update;
 if invitation.id is null or not (public.is_superadmin() or (invitation.role='student' and public.academic_manager(invitation.institution_id))) then raise exception 'Forbidden' using errcode='42501';end if;
 if not public.is_superadmin() and exists(select 1 from public.registration_invites v where v.email=invitation.email and v.role<>'student' and v.accepted_at is null and v.expires_at>now()) then raise exception 'Forbidden' using errcode='42501';end if;
 if invitation.accepted_at is not null or invitation.expires_at<=now() or invitation.credentials_issued_at is not null
 or not public.institution_email_allowed(invitation.institution_id,invitation.email) then raise exception 'Invitation unavailable' using errcode='23514';end if;
 select * into auth_user from auth.users u where lower(u.email)=invitation.email;
 if not public.is_superadmin() and exists(select 1 from public.memberships m where m.user_id=auth_user.id and m.role<>'student') then raise exception 'Forbidden' using errcode='42501';end if;
 if auth_user.email_confirmed_at is not null then raise exception 'Account already confirmed' using errcode='23514';end if;
 update public.registration_invites v set credentials_issued_at=now() where v.id=invite_id;
 return query select invitation.email,invitation.institution_id,auth_user.id;
end; $$;

-- Minimal Auth data needed to distinguish students with an initial, unnamed account.
create function public.registrar_student_roster(inst uuid)
returns table(id uuid,full_name text,email text) language plpgsql stable security definer set search_path='' as $$
begin
 if not public.academic_manager(inst) then raise exception 'Forbidden' using errcode='42501';end if;
 return query select p.id,p.full_name,coalesce(u.email,'')::text from public.memberships m
 join public.profiles p on p.id=m.user_id join auth.users u on u.id=p.id
 where m.institution_id=inst and m.role='student' order by p.full_name,p.id;
end; $$;
revoke execute on function public.registrar_student_roster(uuid) from public,anon;
grant execute on function public.registrar_student_roster(uuid) to authenticated;

notify pgrst, 'reload schema';

-- SOURCE: 202611090001_institution_routes.sql
-- Stable, unique public route labels; institution names can change independently.
alter table public.institutions add column url_slug text;
update public.institutions set url_slug=case
 when lower(code) ~ '^[a-z0-9]+(-[a-z0-9]+)*$' then lower(code)
 else 'vu-'||replace(id::text,'-','') end;
alter table public.institutions alter column url_slug set not null;
alter table public.institutions add constraint institution_url_slug_unique unique(url_slug),
 add constraint institution_url_slug_valid check(length(url_slug) between 2 and 64 and url_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
create function public.institution_route_slug() returns trigger language plpgsql set search_path='' as $$
begin
 if new.url_slug is null or new.url_slug='' then
  if TG_OP='UPDATE' then new.url_slug=old.url_slug;
  else new.url_slug=case when lower(new.code) ~ '^[a-z0-9]+(-[a-z0-9]+)*$' then lower(new.code) else 'vu-'||replace(new.id::text,'-','') end;end if;
 end if;
 return new;
end; $$;
create trigger institution_route_slug before insert or update on public.institutions for each row execute function public.institution_route_slug();
revoke execute on function public.institution_route_slug() from public,anon,authenticated;
notify pgrst,'reload schema';

-- SOURCE: 202611090002_native_learning.sql
-- Native ISVU learning workspace. Independent of mailboxes and Moodle accounts.
-- All writes go through bounded RPCs; read access follows current course membership.
create table public.learning_materials (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null,
  course_id uuid not null,
  title text not null check(length(btrim(title)) between 2 and 200),
  body text not null default '' check(length(body)<=20000),
  resource_url text not null default '' check(length(resource_url)<=2048 and (resource_url='' or resource_url ~ '^https://[^[:space:]@]+$')),
  published boolean not null default false,
  revision integer not null default 1 check(revision>0),
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key(institution_id,course_id) references public.courses(institution_id,id),
  check(length(btrim(body))>0 or resource_url<>'')
);
create table public.learning_assignments (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null,
  course_id uuid not null,
  title text not null check(length(btrim(title)) between 2 and 200),
  instructions text not null check(length(btrim(instructions)) between 2 and 20000),
  due_at timestamptz,
  max_points numeric(8,2) not null default 100 check(max_points>0 and max_points<=10000),
  allow_late boolean not null default false,
  published boolean not null default false,
  revision integer not null default 1 check(revision>0),
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(institution_id,course_id,id),
  foreign key(institution_id,course_id) references public.courses(institution_id,id)
);
create table public.learning_submissions (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null,
  course_id uuid not null,
  assignment_id uuid not null,
  student_id uuid not null references public.profiles(id),
  body text not null default '' check(length(body)<=20000),
  resource_url text not null default '' check(length(resource_url)<=2048 and (resource_url='' or resource_url ~ '^https://[^[:space:]@]+$')),
  revision integer not null default 1 check(revision>0),
  submitted_at timestamptz not null default now(),
  score numeric(8,2) check(score>=0 and score<=10000),
  feedback text not null default '' check(length(feedback)<=5000),
  graded_by uuid references public.profiles(id),
  graded_at timestamptz,
  unique(assignment_id,student_id),
  foreign key(institution_id,course_id,assignment_id) references public.learning_assignments(institution_id,course_id,id),
  check(length(btrim(body))>0 or resource_url<>''),
  check((score is null and graded_by is null and graded_at is null) or (score is not null and graded_by is not null and graded_at is not null))
);
create index learning_material_course on public.learning_materials(course_id,created_at,id);
create index learning_assignment_course on public.learning_assignments(course_id,created_at,id);
create index learning_submission_course on public.learning_submissions(course_id,submitted_at,id);

alter table public.learning_materials enable row level security;
alter table public.learning_assignments enable row level security;
alter table public.learning_submissions enable row level security;
create policy learning_material_read on public.learning_materials for select to authenticated
  using(public.course_staff(institution_id,course_id) or (published and public.enrolled(course_id)));
create policy learning_assignment_read on public.learning_assignments for select to authenticated
  using(public.course_staff(institution_id,course_id) or (published and public.enrolled(course_id)));
create policy learning_submission_read on public.learning_submissions for select to authenticated
  using(public.course_staff(institution_id,course_id) or (student_id=auth.uid() and public.enrolled(course_id)));
revoke all on public.learning_materials,public.learning_assignments,public.learning_submissions from public,anon,authenticated;
grant select on public.learning_materials,public.learning_assignments,public.learning_submissions to authenticated;
grant all on public.learning_materials,public.learning_assignments,public.learning_submissions to service_role;

-- Stable local course identifiers remain available for a future Moodle adapter.
create function public.learning_courses() returns table (
  id uuid,institution_id uuid,institution_name text,name text,code text,semester_name text,academic_year_name text,can_manage boolean,can_submit boolean
) language sql stable security definer set search_path='' as $$
  select c.id,c.institution_id,i.name,c.name,c.code,s.name,y.name,
    public.course_staff(c.institution_id,c.id),public.enrolled(c.id)
  from public.courses c join public.institutions i on i.id=c.institution_id
    join public.semesters s on s.id=c.semester_id and s.institution_id=c.institution_id
    join public.academic_years y on y.id=s.academic_year_id and y.institution_id=c.institution_id
  where public.course_staff(c.institution_id,c.id) or public.enrolled(c.id)
  order by i.name,y.starts_on desc,c.name,c.id;
$$;

create function public.learning_save_material(
  target_course uuid,item_title text,item_body text,item_url text,item_published boolean,
  target uuid default null,expected integer default 0
) returns uuid language plpgsql security definer set search_path='' as $$
declare c public.courses; m public.learning_materials; result uuid;
begin
  select * into c from public.courses where id=target_course;
  if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if target is null then
    if expected is distinct from 0 then raise exception 'LEARNING_CONFLICT'; end if;
    insert into public.learning_materials(institution_id,course_id,title,body,resource_url,published,created_by)
      values(c.institution_id,c.id,btrim(item_title),btrim(item_body),btrim(item_url),item_published,auth.uid()) returning id into result;
  else
    select * into m from public.learning_materials where id=target and course_id=c.id for update;
    if m.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
    if m.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
    update public.learning_materials set title=btrim(item_title),body=btrim(item_body),resource_url=btrim(item_url),
      published=item_published,updated_at=clock_timestamp(),revision=revision+1 where id=m.id returning id into result;
  end if;
  return result;
end; $$;

create function public.learning_save_assignment(
  target_course uuid,item_title text,item_instructions text,item_due timestamptz,item_max numeric,
  item_published boolean,item_late boolean,target uuid default null,expected integer default 0
) returns uuid language plpgsql security definer set search_path='' as $$
declare c public.courses; a public.learning_assignments; result uuid;
begin
  select * into c from public.courses where id=target_course;
  if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if item_max is null or item_max<=0 or item_max>10000 or item_max<>round(item_max,2) then raise exception 'LEARNING_INVALID'; end if;
  if item_due is not null and not isfinite(item_due) then raise exception 'LEARNING_INVALID'; end if;
  if target is null then
    if expected is distinct from 0 then raise exception 'LEARNING_CONFLICT'; end if;
    insert into public.learning_assignments(institution_id,course_id,title,instructions,due_at,max_points,published,allow_late,created_by)
      values(c.institution_id,c.id,btrim(item_title),btrim(item_instructions),item_due,item_max,item_published,item_late,auth.uid()) returning id into result;
  else
    select * into a from public.learning_assignments where id=target and course_id=c.id for update;
    if a.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
    if a.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
    if a.max_points<>item_max and exists(select 1 from public.learning_submissions where assignment_id=a.id) then raise exception 'LEARNING_POINTS_LOCKED'; end if;
    update public.learning_assignments set title=btrim(item_title),instructions=btrim(item_instructions),due_at=item_due,
      max_points=item_max,published=item_published,allow_late=item_late,updated_at=clock_timestamp(),revision=revision+1
      where id=a.id returning id into result;
  end if;
  return result;
end; $$;

create function public.learning_submit(target uuid,answer text,answer_url text,expected integer default 0)
returns uuid language plpgsql security definer set search_path='' as $$
declare a public.learning_assignments; s public.learning_submissions; result uuid;
begin
  -- Same lock order for assignment editing, submission and grading.
  select * into a from public.learning_assignments where id=target for update;
  if a.id is null or not a.published or not public.enrolled(a.course_id) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if a.due_at is not null and clock_timestamp()>a.due_at and not a.allow_late then raise exception 'LEARNING_DEADLINE'; end if;
  select * into s from public.learning_submissions where assignment_id=a.id and student_id=auth.uid() for update;
  if s.id is null then
    if expected is distinct from 0 then raise exception 'LEARNING_CONFLICT'; end if;
    insert into public.learning_submissions(institution_id,course_id,assignment_id,student_id,body,resource_url)
      values(a.institution_id,a.course_id,a.id,auth.uid(),btrim(answer),btrim(answer_url)) returning id into result;
  else
    if s.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
    if s.graded_at is not null then raise exception 'LEARNING_GRADED'; end if;
    update public.learning_submissions set body=btrim(answer),resource_url=btrim(answer_url),
      submitted_at=clock_timestamp(),revision=revision+1 where id=s.id returning id into result;
  end if;
  return result;
end; $$;

create function public.learning_grade(target uuid,points numeric,note text,expected integer)
returns void language plpgsql security definer set search_path='' as $$
declare a public.learning_assignments; s public.learning_submissions; aid uuid;
begin
  select assignment_id into aid from public.learning_submissions where id=target;
  select * into a from public.learning_assignments where id=aid for update;
  if a.id is null or not public.course_staff(a.institution_id,a.course_id) then raise exception 'LEARNING_FORBIDDEN'; end if;
  select * into s from public.learning_submissions where id=target for update;
  if s.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
  if s.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
  if points is null or points<0 or points>a.max_points or points<>round(points,2) then raise exception 'LEARNING_INVALID'; end if;
  update public.learning_submissions set score=points,feedback=note,graded_by=auth.uid(),
    graded_at=clock_timestamp(),revision=revision+1 where id=s.id;
end; $$;

revoke execute on function public.learning_courses(),public.learning_save_material(uuid,text,text,text,boolean,uuid,integer),
  public.learning_save_assignment(uuid,text,text,timestamptz,numeric,boolean,boolean,uuid,integer),
  public.learning_submit(uuid,text,text,integer),public.learning_grade(uuid,numeric,text,integer) from public,anon;
grant execute on function public.learning_courses(),public.learning_save_material(uuid,text,text,text,boolean,uuid,integer),
  public.learning_save_assignment(uuid,text,text,timestamptz,numeric,boolean,boolean,uuid,integer),
  public.learning_submit(uuid,text,text,integer),public.learning_grade(uuid,numeric,text,integer) to authenticated;
notify pgrst,'reload schema';

-- SOURCE: 202611090003_learning_files.sql
-- Private attachments for native learning materials and assignment instructions.
-- Supabase Storage must be enabled. Keep this bucket private.
alter table public.learning_materials add constraint learning_material_course_id unique(institution_id,course_id,id);
create table public.learning_files (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null,
  course_id uuid not null,
  material_id uuid,
  assignment_id uuid,
  object_path text not null unique,
  file_name text not null check(length(file_name) between 1 and 200 and file_name !~ '[[:cntrl:]/\\]'),
  mime_type text not null check(mime_type in ('image/png','image/jpeg','image/gif','image/webp','video/mp4','video/webm','application/pdf','text/plain','application/zip','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation')),
  byte_size bigint not null check(byte_size between 1 and 52428800),
  status text not null default 'pending' check(status in ('pending','ready')),
  uploaded_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  check((material_id is not null)::integer + (assignment_id is not null)::integer=1),
  foreign key(institution_id,course_id,material_id) references public.learning_materials(institution_id,course_id,id),
  foreign key(institution_id,course_id,assignment_id) references public.learning_assignments(institution_id,course_id,id)
);
create index learning_files_material on public.learning_files(material_id,id);
create index learning_files_assignment on public.learning_files(assignment_id,id);
create index learning_files_course on public.learning_files(course_id,id);
alter table public.learning_files enable row level security;

create function public.learning_file_access(target_path text,editing boolean default false) returns boolean
language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.learning_files f
    left join public.learning_materials m on m.id=f.material_id
    left join public.learning_assignments a on a.id=f.assignment_id
    where f.object_path=target_path and
    (public.course_staff(f.institution_id,f.course_id) or
      (not editing and f.status='ready' and coalesce(m.published,a.published,false) and public.enrolled(f.course_id))));
$$;
create policy learning_files_read on public.learning_files for select to authenticated
  using(public.learning_file_access(object_path));
revoke all on public.learning_files from public,anon,authenticated;
grant select on public.learning_files to authenticated;
grant all on public.learning_files to service_role;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('merlin-files','merlin-files',false,52428800,array[
  'image/png','image/jpeg','image/gif','image/webp','video/mp4','video/webm','application/pdf','text/plain','application/zip',
  'application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'
]) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

create policy merlin_object_read on storage.objects for select to authenticated
  using(bucket_id='merlin-files' and public.learning_file_access(name));
create policy merlin_object_insert on storage.objects for insert to authenticated with check(
  bucket_id='merlin-files' and public.learning_file_access(name,true) and exists(
    select 1 from public.learning_files f where f.object_path=name and f.status='pending'
      and f.uploaded_by=auth.uid() and f.created_at>now()-interval '15 minutes'));
create policy merlin_object_delete on storage.objects for delete to authenticated
  using(bucket_id='merlin-files' and public.learning_file_access(name,true));

create function public.learning_reserve_file(kind text,target uuid,filename text,mimetype text,bytes bigint)
returns public.learning_files language plpgsql security definer set search_path='' as $$
declare inst uuid; cid uuid; result public.learning_files; fid uuid=gen_random_uuid();
begin
  if kind='material' then
    select institution_id,course_id into inst,cid from public.learning_materials where id=target for update;
  elsif kind='assignment' then
    select institution_id,course_id into inst,cid from public.learning_assignments where id=target for update;
  else raise exception 'LEARNING_INVALID'; end if;
  if cid is null or not public.course_staff(inst,cid) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if (select count(*) from public.learning_files where material_id=target or assignment_id=target)>=20 then raise exception 'LEARNING_FILE_LIMIT'; end if;
  insert into public.learning_files(id,institution_id,course_id,material_id,assignment_id,object_path,file_name,mime_type,byte_size,uploaded_by)
  values(fid,inst,cid,case when kind='material' then target end,case when kind='assignment' then target end,
    cid::text||'/'||fid::text||'/attachment',filename,mimetype,bytes,auth.uid()) returning * into result;
  return result;
end; $$;

create function public.learning_complete_file(target uuid) returns void language plpgsql security definer set search_path='' as $$
declare f public.learning_files; obj storage.objects;
begin
  select * into f from public.learning_files where id=target for update;
  if f.id is null or f.uploaded_by<>auth.uid() or not public.learning_file_access(f.object_path,true) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if f.status='ready' then return; end if;
  select * into obj from storage.objects where bucket_id='merlin-files' and name=f.object_path;
  if obj.id is null or (obj.metadata->>'size')::bigint is distinct from f.byte_size
    or obj.metadata->>'mimetype' is distinct from f.mime_type then raise exception 'LEARNING_FILE_MISMATCH'; end if;
  update public.learning_files set status='ready' where id=f.id;
end; $$;

create function public.learning_remove_file(target uuid) returns void language plpgsql security definer set search_path='' as $$
declare f public.learning_files;
begin
  select * into f from public.learning_files where id=target for update;
  if f.id is null or not public.learning_file_access(f.object_path,true) then raise exception 'LEARNING_FORBIDDEN'; end if;
  if exists(select 1 from storage.objects where bucket_id='merlin-files' and name=f.object_path) then raise exception 'LEARNING_FILE_PRESENT'; end if;
  delete from public.learning_files where id=f.id;
end; $$;

revoke execute on function public.learning_file_access(text,boolean),public.learning_reserve_file(text,uuid,text,text,bigint),public.learning_complete_file(uuid),public.learning_remove_file(uuid) from public,anon;
grant execute on function public.learning_file_access(text,boolean),public.learning_reserve_file(text,uuid,text,text,bigint),public.learning_complete_file(uuid),public.learning_remove_file(uuid) to authenticated;
notify pgrst,'reload schema';

-- SOURCE: 202611090004_learning_files_1gb.sql
-- Raise application and bucket limits to 1 GiB per attachment.
-- Hosted projects also need Storage Settings > Global file size limit >= 1 GiB.
-- Supabase Free is capped at 50 MB; this migration cannot change the project plan.
alter table public.learning_files drop constraint learning_files_byte_size_check;
alter table public.learning_files add constraint learning_files_byte_size_check
  check(byte_size between 1 and 1073741824);
update storage.buckets set file_size_limit=1073741824,public=false where id='merlin-files';
notify pgrst,'reload schema';

-- SOURCE: 202611100001_learning_quizzes.sql
-- Native single-choice quizzes. Answer keys are separate from student-readable questions.
create table public.learning_quizzes (
  id uuid primary key default gen_random_uuid(),institution_id uuid not null,course_id uuid not null,
  title text not null check(length(btrim(title)) between 2 and 200),
  description text not null default '' check(length(description)<=5000),
  opens_at timestamptz,closes_at timestamptz,published boolean not null default false,
  max_points integer not null check(max_points between 1 and 2000),
  revision integer not null default 1 check(revision>0),
  created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),unique(institution_id,course_id,id),
  check(opens_at is null or isfinite(opens_at)),check(closes_at is null or isfinite(closes_at)),
  check(opens_at is null or closes_at is null or closes_at>opens_at),
  foreign key(institution_id,course_id) references public.courses(institution_id,id)
);
create table public.learning_quiz_questions (
  id uuid primary key default gen_random_uuid(),institution_id uuid not null,course_id uuid not null,quiz_id uuid not null,
  position integer not null check(position between 1 and 20),
  prompt text not null check(length(btrim(prompt)) between 2 and 1000),choices jsonb not null,
  points integer not null check(points between 1 and 100),unique(quiz_id,position),
  foreign key(institution_id,course_id,quiz_id) references public.learning_quizzes(institution_id,course_id,id)
);
create table public.learning_quiz_keys (
  question_id uuid primary key references public.learning_quiz_questions(id) on delete cascade,
  correct_index integer not null check(correct_index between 0 and 5)
);
create table public.learning_quiz_attempts (
  id uuid primary key default gen_random_uuid(),institution_id uuid not null,course_id uuid not null,quiz_id uuid not null,
  student_id uuid not null references public.profiles(id),answers jsonb not null,
  score integer not null check(score>=0),max_points integer not null check(max_points>0 and score<=max_points),
  submitted_at timestamptz not null default now(),unique(quiz_id,student_id),
  foreign key(institution_id,course_id,quiz_id) references public.learning_quizzes(institution_id,course_id,id)
);
create index learning_quizzes_course on public.learning_quizzes(course_id,id);
create index learning_quiz_questions_course on public.learning_quiz_questions(course_id,quiz_id,position);
create index learning_quiz_attempts_course on public.learning_quiz_attempts(course_id,student_id,id);
alter table public.learning_quizzes enable row level security;
alter table public.learning_quiz_questions enable row level security;
alter table public.learning_quiz_keys enable row level security;
alter table public.learning_quiz_attempts enable row level security;
create policy learning_quiz_read on public.learning_quizzes for select to authenticated
 using(public.course_staff(institution_id,course_id) or (published and public.enrolled(course_id)));
create policy learning_quiz_question_read on public.learning_quiz_questions for select to authenticated
 using(public.course_staff(institution_id,course_id) or exists(select 1 from public.learning_quizzes q where q.id=quiz_id and q.published and public.enrolled(q.course_id)
   and (q.opens_at is null or q.opens_at<=now()) and (q.closes_at is null or q.closes_at>=now()
    or exists(select 1 from public.learning_quiz_attempts a where a.quiz_id=q.id and a.student_id=auth.uid()))));
create policy learning_quiz_key_read on public.learning_quiz_keys for select to authenticated
 using(exists(select 1 from public.learning_quiz_questions q where q.id=question_id and public.course_staff(q.institution_id,q.course_id)));
create policy learning_quiz_attempt_read on public.learning_quiz_attempts for select to authenticated
 using(public.course_staff(institution_id,course_id) or (student_id=auth.uid() and public.enrolled(course_id)));
revoke all on public.learning_quizzes,public.learning_quiz_questions,public.learning_quiz_keys,public.learning_quiz_attempts from public,anon,authenticated;
grant select on public.learning_quizzes,public.learning_quiz_questions,public.learning_quiz_keys,public.learning_quiz_attempts to authenticated;
grant all on public.learning_quizzes,public.learning_quiz_questions,public.learning_quiz_keys,public.learning_quiz_attempts to service_role;

create function public.learning_save_quiz(target_course uuid,item_title text,item_description text,item_opens timestamptz,item_closes timestamptz,
 item_published boolean,questions jsonb,target uuid default null,expected integer default 0)
returns uuid language plpgsql security definer set search_path='' as $$
declare c public.courses; q public.learning_quizzes; entry jsonb; choice jsonb; current_questions jsonb;
 result uuid; question_id uuid; position integer=0; total integer=0; correct integer; pts integer;
begin
 select * into c from public.courses where id=target_course;
 if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 if questions is null or jsonb_typeof(questions)<>'array' then raise exception 'LEARNING_INVALID'; end if;
 if jsonb_array_length(questions) not between 1 and 20 then raise exception 'LEARNING_INVALID'; end if;
 for entry in select value from jsonb_array_elements(questions) loop
  if jsonb_typeof(entry)<>'object' or jsonb_typeof(entry->'prompt') is distinct from 'string'
   or length(btrim(entry->>'prompt')) not between 2 and 1000 or jsonb_typeof(entry->'choices') is distinct from 'array'
   or jsonb_typeof(entry->'correct_index') is distinct from 'number' or (entry->>'correct_index') !~ '^[0-9]+$'
   or jsonb_typeof(entry->'points') is distinct from 'number' or (entry->>'points') !~ '^[0-9]+$' then raise exception 'LEARNING_INVALID'; end if;
  if jsonb_array_length(entry->'choices') not between 2 and 6 then raise exception 'LEARNING_INVALID'; end if;
  correct=(entry->>'correct_index')::integer; pts=(entry->>'points')::integer;
  if correct<0 or correct>=jsonb_array_length(entry->'choices') or pts not between 1 and 100 then raise exception 'LEARNING_INVALID'; end if;
  for choice in select value from jsonb_array_elements(entry->'choices') loop
   if jsonb_typeof(choice)<>'string' or length(btrim(choice #>> '{}')) not between 1 and 200 then raise exception 'LEARNING_INVALID'; end if;
  end loop;
  total=total+pts;
 end loop;
 if target is null then
  if expected is distinct from 0 then raise exception 'LEARNING_CONFLICT'; end if;
  insert into public.learning_quizzes(institution_id,course_id,title,description,opens_at,closes_at,published,max_points,created_by)
   values(c.institution_id,c.id,btrim(item_title),btrim(item_description),item_opens,item_closes,item_published,total,auth.uid()) returning id into result;
 else
  select * into q from public.learning_quizzes where id=target and course_id=c.id for update;
  if q.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
  if q.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
  select jsonb_agg(jsonb_build_object('prompt',r.prompt,'choices',r.choices,'correct_index',k.correct_index,'points',r.points) order by r.position)
   into current_questions from public.learning_quiz_questions r join public.learning_quiz_keys k on k.question_id=r.id where r.quiz_id=q.id;
  if current_questions is distinct from questions and exists(select 1 from public.learning_quiz_attempts where quiz_id=q.id) then raise exception 'LEARNING_QUIZ_LOCKED'; end if;
  update public.learning_quizzes set title=btrim(item_title),description=btrim(item_description),opens_at=item_opens,closes_at=item_closes,
   published=item_published,max_points=total,revision=revision+1,updated_at=clock_timestamp() where id=q.id;
  result=q.id;
  if current_questions=questions then return result; end if;
  delete from public.learning_quiz_questions where quiz_id=q.id;
 end if;
 for entry in select value from jsonb_array_elements(questions) loop
  position=position+1;
  insert into public.learning_quiz_questions(institution_id,course_id,quiz_id,position,prompt,choices,points)
   values(c.institution_id,c.id,result,position,btrim(entry->>'prompt'),entry->'choices',(entry->>'points')::integer) returning id into question_id;
  insert into public.learning_quiz_keys(question_id,correct_index) values(question_id,(entry->>'correct_index')::integer);
 end loop;
 return result;
end; $$;

create function public.learning_submit_quiz(target uuid,expected integer,responses jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare q public.learning_quizzes; entry record; question public.learning_quiz_questions; total integer=0; result uuid;
begin
 select * into q from public.learning_quizzes where id=target for update;
 if q.id is null or not q.published or not public.enrolled(q.course_id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 if q.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
 if (q.opens_at is not null and clock_timestamp()<q.opens_at) or (q.closes_at is not null and clock_timestamp()>q.closes_at) then raise exception 'LEARNING_QUIZ_CLOSED'; end if;
 if exists(select 1 from public.learning_quiz_attempts where quiz_id=q.id and student_id=auth.uid()) then raise exception 'LEARNING_QUIZ_DONE'; end if;
 if responses is null or jsonb_typeof(responses)<>'object' then raise exception 'LEARNING_INVALID'; end if;
 for entry in select * from jsonb_each(responses) loop
  select * into question from public.learning_quiz_questions where id::text=entry.key and quiz_id=q.id;
  if question.id is null or jsonb_typeof(entry.value)<>'number' or (entry.value #>> '{}') !~ '^[0-9]+$'
   then raise exception 'LEARNING_INVALID'; end if;
  if (entry.value #>> '{}')::integer<0 or (entry.value #>> '{}')::integer>=jsonb_array_length(question.choices) then raise exception 'LEARNING_INVALID'; end if;
 end loop;
 select coalesce(sum(r.points),0)::integer into total from public.learning_quiz_questions r
  join public.learning_quiz_keys k on k.question_id=r.id where r.quiz_id=q.id
   and responses->>r.id::text=k.correct_index::text;
 insert into public.learning_quiz_attempts(institution_id,course_id,quiz_id,student_id,answers,score,max_points)
  values(q.institution_id,q.course_id,q.id,auth.uid(),responses,total,q.max_points) returning id into result;
 return result;
end; $$;
revoke execute on function public.learning_save_quiz(uuid,text,text,timestamptz,timestamptz,boolean,jsonb,uuid,integer),public.learning_submit_quiz(uuid,integer,jsonb) from public,anon;
grant execute on function public.learning_save_quiz(uuid,text,text,timestamptz,timestamptz,boolean,jsonb,uuid,integer),public.learning_submit_quiz(uuid,integer,jsonb) to authenticated;
notify pgrst,'reload schema';

-- SOURCE: 202611100002_learning_sections.sql
-- Native course sections and structured content. Apply after the quiz migration.
-- Student enrollment and official ISVU records remain owned by the registrar.
do $$ begin
 if to_regclass('public.learning_quizzes') is null then
  raise exception 'Najprije primijenite 202611100001_learning_quizzes.sql u ISVU projektu.';
 end if;
end $$;
create table public.learning_sections (
 id uuid primary key default gen_random_uuid(),
 institution_id uuid not null,
 course_id uuid not null,
 title text not null check(length(btrim(title)) between 2 and 200),
 summary text not null default '' check(length(summary)<=5000),
 published boolean not null default true,
 sort_order integer not null check(sort_order>0),
 revision integer not null default 1 check(revision>0),
 unique(institution_id,course_id,id),
 foreign key(institution_id,course_id) references public.courses(institution_id,id)
);
create index learning_section_course on public.learning_sections(course_id,sort_order,id);
alter table public.learning_sections enable row level security;
create policy learning_section_read on public.learning_sections for select to authenticated
 using(public.course_staff(institution_id,course_id) or (published and public.enrolled(course_id)));
revoke all on public.learning_sections from public,anon,authenticated;
grant select on public.learning_sections to authenticated;
grant all on public.learning_sections to service_role;

alter table public.learning_materials add column section_id uuid, add column sort_order integer not null default 1,
 add column resource_kind text not null default 'text' check(resource_kind in ('text','page','file','folder','url')),
 add column rich_body jsonb;
alter table public.learning_assignments add column section_id uuid, add column sort_order integer not null default 1,
 add column rich_body jsonb;
alter table public.learning_quizzes add column section_id uuid, add column sort_order integer not null default 1;
alter table public.learning_materials add foreign key(institution_id,course_id,section_id) references public.learning_sections(institution_id,course_id,id);
alter table public.learning_assignments add foreign key(institution_id,course_id,section_id) references public.learning_sections(institution_id,course_id,id);
alter table public.learning_quizzes add foreign key(institution_id,course_id,section_id) references public.learning_sections(institution_id,course_id,id);
-- Existing activities keep their content and appear in the General section.
with ordered as (
 select id, row_number() over(partition by course_id order by created_at,id)::integer n from public.learning_materials
) update public.learning_materials m set sort_order=o.n from ordered o where o.id=m.id;

create function public.learning_section_visible(target uuid) returns boolean
 language sql stable security definer set search_path='' as $$
 select target is null or exists(select 1 from public.learning_sections s where s.id=target
  and (public.course_staff(s.institution_id,s.course_id) or (s.published and public.enrolled(s.course_id))));
$$;
alter policy learning_material_read on public.learning_materials using(public.course_staff(institution_id,course_id)
 or (published and public.enrolled(course_id) and public.learning_section_visible(section_id)));
alter policy learning_assignment_read on public.learning_assignments using(public.course_staff(institution_id,course_id)
 or (published and public.enrolled(course_id) and public.learning_section_visible(section_id)));
alter policy learning_quiz_read on public.learning_quizzes using(public.course_staff(institution_id,course_id)
 or (published and public.enrolled(course_id) and public.learning_section_visible(section_id)));
-- Question policy already uses the quiz's RLS. Attempts and submissions remain visible
-- as the learner's own history even if the teaching section is subsequently hidden.
create or replace function public.learning_file_access(target_path text,editing boolean default false) returns boolean
 language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.learning_files f
  left join public.learning_materials m on m.id=f.material_id
  left join public.learning_assignments a on a.id=f.assignment_id
  where f.object_path=target_path and (public.course_staff(f.institution_id,f.course_id) or
   (not editing and f.status='ready' and coalesce(m.published,a.published,false) and public.enrolled(f.course_id)
    and public.learning_section_visible(coalesce(m.section_id,a.section_id)))));
$$;
-- Defense in depth: old RPCs and direct authenticated calls cannot submit into hidden sections.
create function public.learning_check_visible_submission() returns trigger language plpgsql security definer set search_path='' as $$
declare visible boolean;
begin
 if auth.uid() is null or public.course_staff(new.institution_id,new.course_id) then return new; end if;
 if tg_table_name='learning_submissions' then
  select published and public.learning_section_visible(section_id) into visible from public.learning_assignments where id=new.assignment_id;
 else
  select published and public.learning_section_visible(section_id) into visible from public.learning_quizzes where id=new.quiz_id;
 end if;
 if visible is distinct from true then raise exception 'LEARNING_FORBIDDEN'; end if;
 return new;
end $$;
create trigger learning_visible_submission before insert or update on public.learning_submissions
 for each row execute function public.learning_check_visible_submission();
create trigger learning_visible_attempt before insert or update on public.learning_quiz_attempts
 for each row execute function public.learning_check_visible_submission();

-- Bounded document tree; renderers never execute HTML from this JSON.
create function public.learning_valid_document(node jsonb,depth integer default 0) returns boolean
 language plpgsql immutable set search_path='' as $$
declare child jsonb; mark jsonb; kind text;
begin
 if node is null then return true; end if;
 if depth>12 or octet_length(node::text)>120000 or jsonb_typeof(node)<>'object' then return false; end if;
 kind=node->>'type';
 if kind is null or kind not in ('doc','paragraph','text','heading','bulletList','orderedList','listItem','blockquote','codeBlock','horizontalRule','hardBreak') then return false; end if;
 if depth=0 and kind<>'doc' then return false; end if;
 if kind='text' and (jsonb_typeof(node->'text') is distinct from 'string' or length(node->>'text')>20000) then return false; end if;
 if node ? 'content' then
  if jsonb_typeof(node->'content')<>'array' or jsonb_array_length(node->'content')>300 then return false; end if;
  for child in select value from jsonb_array_elements(node->'content') loop
   if not public.learning_valid_document(child,depth+1) then return false; end if;
  end loop;
 end if;
 if node ? 'marks' then
  if jsonb_typeof(node->'marks')<>'array' or jsonb_array_length(node->'marks')>8 then return false; end if;
  for mark in select value from jsonb_array_elements(node->'marks') loop
   if coalesce(mark->>'type','') not in ('bold','italic','underline','strike','code','link') then return false; end if;
   if mark->>'type'='link' and (coalesce(mark->'attrs'->>'href','') !~ '^https://[^[:space:]@]+$' or length(mark->'attrs'->>'href')>2048) then return false; end if;
  end loop;
 end if;
 return true;
end $$;
alter table public.learning_materials add check(public.learning_valid_document(rich_body));
alter table public.learning_assignments add check(public.learning_valid_document(rich_body));

create function public.learning_save_section(target_course uuid,item_title text,item_summary text,item_published boolean,
 target uuid default null,expected integer default 0) returns uuid language plpgsql security definer set search_path='' as $$
declare c public.courses; s public.learning_sections; result uuid;
begin
 select * into c from public.courses where id=target_course for update;
 if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 if target is null then
  if expected is distinct from 0 then raise exception 'LEARNING_CONFLICT'; end if;
  insert into public.learning_sections(institution_id,course_id,title,summary,published,sort_order)
   values(c.institution_id,c.id,btrim(item_title),btrim(item_summary),item_published,
    coalesce((select max(sort_order) from public.learning_sections where course_id=c.id),0)+1) returning id into result;
 else
  select * into s from public.learning_sections where id=target and course_id=c.id for update;
  if s.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
  if s.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
  update public.learning_sections set title=btrim(item_title),summary=btrim(item_summary),published=item_published,revision=revision+1 where id=s.id;
  result=s.id;
 end if;
 return result;
end $$;

-- One transaction saves the existing, fully validated activity AND its placement/content.
create function public.learning_save_content(target_course uuid,kind text,item jsonb,target_section uuid default null,
 item_resource text default 'text',document jsonb default null) returns uuid language plpgsql security definer set search_path='' as $$
declare c public.courses; result uuid; old_section uuid; old_sort integer; target uuid; expected integer;
begin
 select * into c from public.courses where id=target_course for update;
 if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 if target_section is not null and not exists(select 1 from public.learning_sections where id=target_section and course_id=c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 if not public.learning_valid_document(document) then raise exception 'LEARNING_INVALID'; end if;
 target=nullif(item->>'target','')::uuid; expected=(item->>'expected')::integer;
 if kind='material' then
  if item_resource not in ('text','page','file','folder','url') then raise exception 'LEARNING_INVALID'; end if;
  if item_resource='url' and coalesce(item->>'item_url','')='' then raise exception 'LEARNING_INVALID'; end if;
  select section_id,sort_order into old_section,old_sort from public.learning_materials where id=target and course_id=c.id;
  result=public.learning_save_material(c.id,item->>'item_title',item->>'item_body',item->>'item_url',(item->>'item_published')::boolean,target,expected);
 elsif kind='assignment' then
  select section_id,sort_order into old_section,old_sort from public.learning_assignments where id=target and course_id=c.id;
  result=public.learning_save_assignment(c.id,item->>'item_title',item->>'item_instructions',(item->>'item_due')::timestamptz,
   (item->>'item_max')::numeric,(item->>'item_published')::boolean,(item->>'item_late')::boolean,target,expected);
 elsif kind='quiz' then
  select section_id,sort_order into old_section,old_sort from public.learning_quizzes where id=target and course_id=c.id;
  result=public.learning_save_quiz(c.id,item->>'item_title',item->>'item_description',(item->>'item_opens')::timestamptz,
   (item->>'item_closes')::timestamptz,(item->>'item_published')::boolean,item->'questions',target,expected);
 else raise exception 'LEARNING_INVALID'; end if;
 if target is null or old_section is distinct from target_section then
  select coalesce(max(position),0)+1 into old_sort from (
   select sort_order position from public.learning_materials where course_id=c.id and section_id is not distinct from target_section
   union all select sort_order from public.learning_assignments where course_id=c.id and section_id is not distinct from target_section
   union all select sort_order from public.learning_quizzes where course_id=c.id and section_id is not distinct from target_section
  ) positions;
 end if;
 if kind='material' then
  if item_resource='file' and (item->>'item_published')::boolean and not exists(
   select 1 from public.learning_files where material_id=result and status='ready'
  ) then raise exception 'LEARNING_FILE_REQUIRED'; end if;
  update public.learning_materials set section_id=target_section,sort_order=old_sort,resource_kind=item_resource,rich_body=document where id=result;
 elsif kind='assignment' then
  update public.learning_assignments set section_id=target_section,sort_order=old_sort,rich_body=document where id=result;
 else update public.learning_quizzes set section_id=target_section,sort_order=old_sort where id=result;
 end if;
 return result;
end $$;

create function public.learning_order_section(target_course uuid,target uuid,expected integer,direction text) returns void
 language plpgsql security definer set search_path='' as $$
declare c public.courses; s public.learning_sections; neighbor public.learning_sections;
begin
 select * into c from public.courses where id=target_course for update;
 if c.id is null or not public.course_staff(c.institution_id,c.id) then raise exception 'LEARNING_FORBIDDEN'; end if;
 select * into s from public.learning_sections where id=target and course_id=c.id for update;
 if s.id is null then raise exception 'LEARNING_FORBIDDEN'; end if;
 if s.revision is distinct from expected then raise exception 'LEARNING_CONFLICT'; end if;
 if direction='delete' then
  if exists(select 1 from public.learning_materials where section_id=s.id)
   or exists(select 1 from public.learning_assignments where section_id=s.id)
   or exists(select 1 from public.learning_quizzes where section_id=s.id) then raise exception 'LEARNING_SECTION_NOT_EMPTY'; end if;
  delete from public.learning_sections where id=s.id;
  return;
 elsif direction='up' then
  select * into neighbor from public.learning_sections where course_id=c.id and sort_order<s.sort_order order by sort_order desc,id limit 1 for update;
 elsif direction='down' then
  select * into neighbor from public.learning_sections where course_id=c.id and sort_order>s.sort_order order by sort_order,id limit 1 for update;
 else raise exception 'LEARNING_INVALID'; end if;
 if neighbor.id is not null then
  update public.learning_sections set sort_order=case when id=s.id then neighbor.sort_order else s.sort_order end,revision=revision+1
   where id in (s.id,neighbor.id);
 end if;
end $$;
